class Pricing {
  constructor(basePrice) {
    this.basePrice = basePrice;
  }

  calculatePrice(demandLevel) {
    return this.basePrice + (demandLevel * 5);
  }
}

class Demand {
  constructor(initialDemand) {
    this.demand = initialDemand;
  }

  updateDemand(change) {
    this.demand += change;
  }

  getDemand() {
    return this.demand;
  }
}

class Store {
  constructor(pricing, demand) {
    this.pricing = pricing;
    this.demand = demand;
  }

  sellProduct() {
    const demandLevel = this.demand.getDemand();
    const price = this.pricing.calculatePrice(demandLevel);
    this.demand.updateDemand(-1);
    return price;
  }
}

