  constructor(){this.level=1;this.xp=0;}
  needed(level){ return level*100; }
  add(amount){this.xp+=amount;let g=0;while(this.xp>=this.needed(this.level)){this.xp-=this.needed(this.level);this.level+=1;g+=1;}return g;}
