class Store {
  constructor(pricing, demand) {
    this.pricing = pricing;
    this.demand = demand;
    this.inventory = {};
  }

  purchase(item) {
    const price = this.pricing.getPrice(item);
    const demand = this.demand.getDemand(item);

    if (demand > 0 && price > 0) {
      console.log(`Purchasing ${item} for $${price}`);
      this.demand.setDemand(item, demand - 1);
      this.inventory[item] = (this.inventory[item] || 0) + 1;
    } else {
      console.log(`Item ${item} is out of demand or not priced.`);
    }
