    };
  }

  getPrice(item) {
    return this.prices[item] || 0;
  }

  debit(amount) {
    // Simulate debiting an account
    console.log(`Debited ${amount} from account.`);
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity = 1) {
    if (this.items[item]) {
      this.items[item] += quantity;
    } else {
      this.items[item] = quantity;
    }
    console.log(`Added ${quantity} ${item}(s) to inventory.`);
  }

  getInventory() {
    return this.items;
  }
}

class Store {
  constructor(economy, inventory) {
    this.economy = economy;
    this.inventory = inventory;
  }

  purchase(item) {
    const price = this.economy.getPrice(item);
    if (price > 0) {
      this.economy.debit(price);
      this.inventory.addItem(item);
    } else {
      console.log(`Item ${item} not found or not available.`);
    }
  }
}

class Customer {
  constructor(store) {
    this.store = store;
  }

  order(item) {
    console.log(`Customer ordered ${item}.`);
    this.store.purchase(item);
  }
}

