class Store {
  constructor(pricing, demand) {
    this.pricing = pricing;
    this.demand = demand;
    this.inventory = {};
  }

  purchase(item, quantity) {
    const price = this.pricing.getPrice(item);
    const availableDemand = this.demand.getDemand(item);

    if (availableDemand >= quantity && price > 0) {
      console.log(`Purchased ${quantity} ${item}(s) for ${price * quantity} gold.`);
      this.demand.setDemand(item, availableDemand - quantity);
      this.inventory[item] = (this.inventory[item] || 0) + quantity;
    } else {
      console.log(`Failed to purchase ${quantity} ${item}(s).`);
    }
  }

  getInventory() {
    return this.inventory;
  }
}

