class Crop {
  constructor(name, growthRate) {
    this.name = name;
    this.growthRate = growthRate;
    this.stage = 0;
  }

  grow() {
    this.stage += this.growthRate;
    return this.stage;
  }

  isReady() {
    return this.stage >= 10;
  }

  getName() {
    return this.name;
  }
}

class Farm {
  constructor() {
    this.crops = [];
  }

  plantCrop(crop) {
    this.crops.push(crop);
  }

  growCrops() {
    this.crops.forEach(crop => crop.grow());
  }

  harvestReadyCrops() {
    return this.crops.filter(crop => crop.isReady()).map(crop => crop.getName());
  }

  getCropStages() {
    return this.crops.map(crop => ({ name: crop.getName(), stage: crop.stage }));
  }
}

class Market {
  constructor() {
    this.prices = { wheat: 5, corn: 4, rice: 6 };
  }

  sellCrop(cropName, quantity) {
    if (this.prices[cropName]) {
      return this.prices[cropName] * quantity;
    }
    return 0;
  }

  getPrices() {
    return { ...this.prices };
  }
}

