class Quest {
  constructor(flags) {
    this.flags = flags;
    this.quests = {};
  }

  addQuest(key, requirement, text) {
    this.quests[key] = { requirement, text };
  }

  getQuest(key) {
    const quest = this.quests[key];
    if (!quest) return "No quest found.";
    if (this.flags.getFlag(quest.requirement)) {
      return quest.text;
    } else {
      return "Quest not available.";
    }
  }
}

// Top-level Coordinator
