    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(listener);
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(listener => listener(data));
    }
  }
}

class Pricing {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('priceChange', this.onPriceChange.bind(this));
  }

  setBasePrice(price) {
    this.basePrice = price;
    this.eventBus.emit('priceUpdate', { price: this.basePrice });
  }

  onPriceChange(change) {
    this.basePrice += change;
    this.eventBus.emit('priceUpdate', { price: this.basePrice });
  }
}

class Demand {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('priceUpdate', this.onPriceUpdate.bind(this));
  }

  onPriceUpdate({ price }) {
    this.currentDemand = Math.max(0, 100 - (price - 50) * 2);
    this.eventBus.emit('demandUpdate', { demand: this.currentDemand });
  }
}

class Store {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('demandUpdate', this.onDemandUpdate.bind(this));
    this.inventory = 100;
  }

  onDemandUpdate({ demand }) {
    console.log(`Current Demand: ${demand}`);
    if (demand > this.inventory) {
      console.log('Restocking...');
      this.inventory += 50;
    } else if (demand < this.inventory / 2) {
      console.log('Reducing stock...');
      this.inventory -= 30;
    }
    console.log(`Current Inventory: ${this.inventory}`);
  }
}

