class Building {
  constructor(name, resourceCost) {
    this.name = name;
    this.resourceCost = resourceCost;
  }

  build(economy) {
    if (economy.canAfford(this.resourceCost)) {
      economy.spendResources(this.resourceCost);
      console.log(`Built ${this.name}`);
      return true;
    } else {
      console.log(`Cannot build ${this.name}: insufficient resources`);
      return false;
    }
  }
}

class Resource {
  constructor(name, initialAmount) {
    this.name = name;
    this.amount = initialAmount;
  }

  add(amount) {
    this.amount += amount;
    console.log(`Added ${amount} ${this.name}`);
  }

  spend(amount) {
    if (this.amount >= amount) {
      this.amount -= amount;
      console.log(`Spent ${amount} ${this.name}`);
      return true;
    } else {
      console.log(`Cannot spend ${amount} ${this.name}: insufficient resources`);
      return false;
    }
  }
}

class Economy {
  constructor() {
    this.resources = {};
  }

  addResource(resource) {
    this.resources[resource.name] = resource;
  }

  canAfford(resourceCost) {
    for (const [resourceName, amount] of Object.entries(resourceCost)) {
      if (this.resources[resourceName].amount < amount) {
        return false;
      }
    }
    return true;
  }

  spendResources(resourceCost) {
    for (const [resourceName, amount] of Object.entries(resourceCost)) {
      this.resources[resourceName].spend(amount);
    }
  }
}

// Demo
