canvas.style.width = '100vw';
canvas.style.height = '100vh';
canvas.width = canvas.clientWidth * devicePixelRatio;
canvas.height = canvas.clientHeight * devicePixelRatio;
const ctx = canvas.getContext('2d');

const TEXTS = [
    "The quick brown fox jumps over the lazy dog.",
    "Programming is fun and challenging.",
    "JavaScript is a versatile language.",
    "Canvas rendering is powerful and flexible."
];
let currentText = TEXTS[Math.floor(Math.random() * TEXTS.length)];
let currentIndex = 0;
let startTime;
let gameOver = false;

function resetGame() {
    currentText = TEXTS[Math.floor(Math.random() * TEXTS.length)];
    currentIndex = 0;
    gameOver = false;
    startTime = performance.now();
}

function drawText() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.font = '24px Arial';
    ctx.fillStyle = '#000';
    ctx.fillText(currentText, 20, 50);
    ctx.fillStyle = '#0f0';
    ctx.fillText(currentText.substring(0, currentIndex), 20, 100);
    ctx.fillStyle = '#f00';
    ctx.fillText(currentText.substring(currentIndex, currentIndex + 1), 20, 100);
}

function update() {
    if (!gameOver) {
        drawText();
        requestAnimationFrame(update);
    }
}

canvas.addEventListener('keydown', (e) => {
    if (e.key === currentText[currentIndex]) {
        currentIndex++;
        if (currentIndex === currentText.length) {
            const endTime = performance.now();
            const timeTaken = ((endTime - startTime) / 1000).toFixed(2);
            ctx.fillStyle = '#000';
            ctx.fillText(`You finished in ${timeTaken} seconds!`, 20, 150);
            gameOver = true;
        }
    }
});

canvas.addEventListener('click', () => {
    if (gameOver) {
        resetGame();
    }
});

resetGame();
