class Economy {
  constructor() {
    this.prices = {
      'sword': 50,
      'shield': 30,
      'potion': 10
    };
    this.balance = 100;
  }

  getPrice(item) {
    return this.prices[item];
  }

  debit(amount) {
    if (this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }

  getBalance() {
    return this.balance;
  }
}

class Wallet {
  constructor(economy) {
    this.economy = economy;
  }

  hasEnoughFunds(item) {
    const price = this.economy.getPrice(item);
    return this.economy.getBalance() >= price;
  }

  spend(item) {
    const price = this.economy.getPrice(item);
    return this.economy.debit(price);
  }

  getBalance() {
    return this.economy.getBalance();
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item) {
    if (this.items[item]) {
      this.items[item]++;
    } else {
      this.items[item] = 1;
    }
  }

  getItems() {
    return this.items;
  }
}

class Shop {
  constructor(wallet, inventory) {
    this.wallet = wallet;
    this.inventory = inventory;
  }

  purchase(item) {
    if (this.wallet.hasEnoughFunds(item)) {
      if (this.wallet.spend(item)) {
        this.inventory.addItem(item);
        return true;
      }
    }
    return false;
  }
}

