class Farm {
  constructor() {
    this.crops = [];
  }

  plantCrop(crop) {
    this.crops.push(crop);
    console.log(`Planted crop: ${crop}`);
  }

  harvestCrops() {
    const harvested = this.crops;
    this.crops = [];
    console.log(`Harvested crops: ${harvested.join(', ')}`);
    return harvested;
  }
}

// Crop system
class Crop {
  constructor(name, price) {
    this.name = name;
    this.price = price;
  }

  toString() {
    return this.name;
  }
}

// Market system
class Market {
  constructor() {
    this.inventory = [];
  }

  sellCrop(crop, price) {
    this.inventory.push({ crop, price });
    console.log(`Sold crop ${crop.name} for ${price}`);
  }

  buyCrop(cropName) {
    const cropEntry = this.inventory.find(entry => entry.crop.name === cropName);
    if (cropEntry) {
      console.log(`Bought crop: ${cropName}`);
      this.inventory = this.inventory.filter(entry => entry.crop.name !== cropName);
      return cropEntry.crop;
    }
    console.log(`Crop ${cropName} not available in market`);
    return null;
  }
}

// Coordinator system
class Coordinator {
  constructor() {
    this.farm = new Farm();
    this.market = new Market();
  }

  plantAndSellCrop(cropName, price) {
    const crop = new Crop(cropName, price);
    this.farm.plantCrop(crop.name);
    this.farm.harvestCrops().forEach(harvestedCrop => {
      this.market.sellCrop(new Crop(harvestedCrop, price), price);
    });
  }

  buyCropFromMarket(cropName) {
    return this.market.buyCrop(cropName);
  }
}

// Demo
