  }

  subscribe(event, listener) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(listener);
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(listener => listener(data));
    }
  }
}

class Trade {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('tradeRequested', this.handleTradeRequest.bind(this));
  }

  requestTrade(item, quantity, withFaction) {
    this.eventBus.emit('tradeRequested', { item, quantity, withFaction });
  }

  handleTradeRequest(data) {
    console.log(`Trade requested for ${data.quantity} ${data.item} with ${data.withFaction}`);
    // Simulate trade success
    this.eventBus.emit('tradeSuccess', { item: data.item, quantity: data.quantity, faction: data.withFaction });
  }
}

class Reputation {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('tradeSuccess', this.increaseReputation.bind(this));
    this.reputation = { 'Faction A': 0, 'Faction B': 0 };
  }

  increaseReputation(data) {
    console.log(`Reputation increased with ${data.faction} for successful trade.`);
    this.reputation[data.faction] += 1;
    console.log(`New reputation with ${data.faction}: ${this.reputation[data.faction]}`);
  }
}

class Faction {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('tradeSuccess', this.logTrade.bind(this));
    this.factions = ['Faction A', 'Faction B'];
  }

  logTrade(data) {
    console.log(`${data.faction} successfully traded ${data.quantity} ${data.item}`);
  }
}

// Demo
