class Pricing {
    constructor(basePrice) {
        this.basePrice = basePrice;
    }

    calculatePrice(quantity) {
        return this.basePrice * quantity;
    }
}

class Demand {
    constructor(baseDemand) {
        this.baseDemand = baseDemand;
    }

    calculateDemand(price) {
        return Math.max(0, this.baseDemand - Math.floor(price / 10));
    }
}

class Store {
    constructor(pricing, demand) {
        this.pricing = pricing;
        this.demand = demand;
        this.stock = 100;
    }

    restock(amount) {
        this.stock += amount;
    }

    sell(quantity) {
        if (quantity > this.stock) {
            console.log("Not enough stock.");
            return 0;
        }
        this.stock -= quantity;
        return quantity;
    }

    getTotalRevenue(price, quantity) {
        return price * quantity;
    }
}

class Coordinator {
    constructor(pricing, demand, store) {
        this.pricing = pricing;
        this.demand = demand;
        this.store = store;
    }

    runSimulation() {
        const quantity = 10;
        const price = this.pricing.calculatePrice(quantity);
        const demand = this.demand.calculateDemand(price);

        console.log(`Base Price: $${this.pricing.basePrice}`);
        console.log(`Quantity: ${quantity}`);
        console.log(`Calculated Price: $${price}`);
        console.log(`Demand: ${demand}`);

        const sold = this.store.sell(Math.min(quantity, demand));
        console.log(`Sold: ${sold}`);

        const revenue = this.store.getTotalRevenue(price, sold);
        console.log(`Total Revenue: $${revenue}`);
    }
}

// Runnable demo
const pricing = new Pricing(15);
const demand = new Demand(50);
const store = new Store(pricing, demand);
const coordinator = new Coordinator(pricing, demand, store);

coordinator.runSimulation();
