// Combat System
class Combat {
  constructor() {
    this.attacks = {
      punch: 10,
      kick: 15,
      slash: 20
    };
  }

  attack(attacker, defender, move) {
    const damage = this.attacks[move] || 0;
    return { attacker, defender, move, damage };
  }
}

// Health System
class Health {
  constructor() {
    this.maxHealth = 100;
  }

  takeDamage(entity, damage) {
    entity.health = Math.max(0, entity.health - damage);
    return entity;
  }

  heal(entity, amount) {
    entity.health = Math.min(this.maxHealth, entity.health + amount);
    return entity;
  }
}

// Loot System
class Loot {
  constructor() {
    this.items = {
      potion: { healAmount: 20 },
      gold: { value: 10 }
    };
  }

  dropLoot() {
    const itemNames = Object.keys(this.items);
    const randomItem = itemNames[Math.floor(Math.random() * itemNames.length)];
    return { item: randomItem, details: this.items[randomItem] };
  }

  applyLoot(entity, loot) {
    if (loot.item === 'potion') {
      Health.prototype.heal(entity, loot.details.healAmount);
    }
    // Add more loot effects here
    return entity;
  }
}

// Coordinator
class GameCoordinator {
  constructor() {
    this.combat = new Combat();
    this.health = new Health();
    this.loot = new Loot();
  }

  startCombat(attacker, defender, move) {
    const { damage } = this.combat.attack(attacker, defender, move);
    this.health.takeDamage(defender, damage);
    console.log(`${attacker.name} attacked ${defender.name} with ${move} for ${damage} damage.`);

    const loot = this.loot.dropLoot();
    console.log(`${defender.name} dropped a ${loot.item}.`);
    this.loot.applyLoot(defender, loot);
    console.log(`${defender.name}'s health is now ${defender.health}.`);
  }
}

