const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

let width, height;
function resize() {
    width = window.innerWidth;
    height = window.innerHeight;
    canvas.width = width * devicePixelRatio;
    canvas.height = height * devicePixelRatio;
    ctx.scale(devicePixelRatio, devicePixelRatio);
    canvas.style.width = `${width}px`;
    canvas.style.height = `${height}px`;
}
resize();
window.addEventListener('resize', resize);

let lastTime = performance.now();
let combo = 0;
let maxCombo = 0;
let fishing = false;
let rodX = width / 2;
let rodY = height - 50;
let lineWidth = 3;
let fishX = Math.random() * width;
let fishY = -50;
let fishSpeed = 2;
let fishCaught = false;

function drawRod() {
    ctx.beginPath();
    ctx.moveTo(rodX, rodY);
    ctx.lineTo(rodX, height);
    ctx.strokeStyle = 'black';
    ctx.lineWidth = lineWidth;
    ctx.stroke();
}

function drawFish() {
    ctx.beginPath();
    ctx.arc(fishX, fishY, 10, 0, Math.PI * 2);
    ctx.fillStyle = 'blue';
    ctx.fill();
}

function update() {
    const now = performance.now();
    const dt = (now - lastTime) / 1000;
    lastTime = now;

    if (fishing) {
        fishY += fishSpeed * dt;
        if (fishY > height) {
            fishY = -50;
            fishX = Math.random() * width;
            combo = 0;
        }
        if (!fishCaught && Math.abs(fishX - rodX) < 20 && fishY > rodY - 10) {
            fishCaught = true;
            combo++;
            maxCombo = Math.max(maxCombo, combo);
        }
    }

    if (fishCaught && fishY > height) {
        fishCaught = false;
        fishSpeed = 2 + Math.min(combo, 10) * 0.1;
    }

    ctx.clearRect(0, 0, width, height);
    drawRod();
    drawFish();
    ctx.fillStyle = 'black';
    ctx.fillText(`Combo: ${combo}`, 10, 20);
    ctx.fillText(`Max Combo: ${maxCombo}`, 10, 40);

    requestAnimationFrame(update);
}

canvas.addEventListener('click', () => {
    if (!fishing) {
        fishing = true;
    }
});

update();
