class LevelUp {
    constructor(skill, experience) {
        this.skill = skill;
        this.experience = experience;
        this.thresholds = [10, 20, 30]; // Thresholds for level up
    }

    checkLevelUp() {
        const currentPoints = this.experience.getPoints();
        const currentSkillLevel = this.skill.getLevel();
        const nextThreshold = this.thresholds[currentSkillLevel - 1];

        if (currentPoints >= nextThreshold) {
            this.skill.improve();
            this.experience.addPoints(-nextThreshold); // Deduct points used for level up
        }
    }
}

