  restockItem(item, quantity) {
    const currentDemand = this.demand.getDemand(item);
    this.demand.setDemand(item, currentDemand + quantity);
    console.log(`Restocked ${item} with ${quantity} units`);
  }

  updatePrice(item, newPrice) {
    this.pricing.setPrice(item, newPrice);
    console.log(`Updated ${item} price to $${newPrice}`);
  }
}

