        this.name = name;
        this.ingredients = ingredients;
    }
}

class Inventory {
    constructor() {
        this.items = {};
    }

    addItem(item, quantity) {
        if (this.items[item]) {
            this.items[item] += quantity;
        } else {
            this.items[item] = quantity;
        }
    }

    removeItem(item, quantity) {
        if (this.items[item] && this.items[item] >= quantity) {
            this.items[item] -= quantity;
            return true;
        }
        return false;
    }

    hasItem(item, quantity) {
        return this.items[item] && this.items[item] >= quantity;
    }

    getItemCount(item) {
        return this.items[item] || 0;
    }
}

class Crafting {
    constructor(inventory) {
        this.inventory = inventory;
        this.recipes = [];
    }

    addRecipe(recipe) {
        this.recipes.push(recipe);
    }

    canCraft(recipeName) {
        const recipe = this.recipes.find(r => r.name === recipeName);
        if (!recipe) return false;
        for (const [item, quantity] of Object.entries(recipe.ingredients)) {
            if (!this.inventory.hasItem(item, quantity)) {
                return false;
            }
        }
        return true;
    }

    craft(recipeName) {
        const recipe = this.recipes.find(r => r.name === recipeName);
        if (!recipe) return false;
        if (!this.canCraft(recipeName)) return false;

        for (const [item, quantity] of Object.entries(recipe.ingredients)) {
            this.inventory.removeItem(item, quantity);
        }
        console.log(`Crafted: ${recipeName}`);
        return true;
    }
}

