const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');
let width, height;
let playerHealth = 100;
let playerX, playerY;
let spawnTimer = 0;
let spawnInterval = 2000;
let enemies = [];
let tapPosition = null;
let tapCooldown = false;
let tapCooldownDuration = 300;

function resize() {
  width = window.innerWidth;
  height = window.innerHeight;
  canvas.width = width * devicePixelRatio;
  canvas.height = height * devicePixelRatio;
  ctx.scale(devicePixelRatio, devicePixelRatio);
  playerX = width / 2;
  playerY = height - 50;
}

resize();
window.addEventListener('resize', resize);

function spawnEnemy() {
  enemies.push({
    x: Math.random() * width,
    y: -50,
    speed: Math.random() * 2 + 1
  });
}

function update() {
  spawnTimer += 16.67;
  if (spawnTimer >= spawnInterval) {
    spawnTimer = 0;
    spawnEnemy();
  }

  enemies.forEach(enemy => {
    enemy.y += enemy.speed;
    if (enemy.y > height) {
      playerHealth -= 10;
      if (playerHealth <= 0) {
        playerHealth = 100;
        enemies = [];
      }
    }
  });

  enemies = enemies.filter(enemy => {
    if (tapPosition) {
      const distance = Math.sqrt((enemy.x - tapPosition.x) ** 2 + (enemy.y - tapPosition.y) ** 2);
      if (distance < 30) {
        tapPosition = null;
        tapCooldown = true;
        setTimeout(() => tapCooldown = false, tapCooldownDuration);
        return false;
      }
    }
    return true;
  });

  if (tapCooldown) {
    tapPosition = null;
  }
}

function draw() {
  ctx.clearRect(0, 0, width, height);

  ctx.fillStyle = 'blue';
  ctx.fillRect(0, height - 30, (playerHealth / 100) * width, 30);

  ctx.fillStyle = 'red';
  ctx.beginPath();
  ctx.arc(playerX, playerY, 10, 0, Math.PI * 2);
  ctx.fill();

  enemies.forEach(enemy => {
    ctx.fillStyle = 'green';
    ctx.beginPath();
    ctx.arc(enemy.x, enemy.y, 10, 0, Math.PI * 2);
    ctx.fill();
  });
}

function gameLoop() {
  update();
  draw();
  requestAnimationFrame(gameLoop);
}

gameLoop();

canvas.addEventListener('click', (event) => {
  if (!tapCooldown) {
    tapPosition = {
      x: event.clientX,
      y: event.clientY
    };
  }
});
