class Combat {
  constructor() {
    this.enemies = [];
  }

  addEnemy(name, health) {
    this.enemies.push({ name, health });
  }

  attack(targetName, damage) {
    const enemy = this.enemies.find(e => e.name === targetName);
    if (enemy) {
      return { target: enemy.name, damage };
    }
    return null;
  }
}

class Health {
  constructor() {
    this.playerHealth = 100;
  }

  takeDamage(amount) {
    this.playerHealth -= amount;
    return { health: this.playerHealth };
  }

  heal(amount) {
    this.playerHealth += amount;
    if (this.playerHealth > 100) {
      this.playerHealth = 100;
    }
    return { health: this.playerHealth };
  }
}

class Loot {
  constructor() {
    this.lootPool = [];
  }

  addLoot(item) {
    this.lootPool.push(item);
  }

  dropLoot() {
    if (this.lootPool.length > 0) {
      const lootIndex = Math.floor(Math.random() * this.lootPool.length);
      return this.lootPool.splice(lootIndex, 1)[0];
    }
    return null;
  }
}

class GameCoordinator {
  constructor() {
    this.combat = new Combat();
    this.health = new Health();
    this.loot = new Loot();

    this.combat.addEnemy('Goblin', 50);
    this.loot.addLoot('Potion of Healing');
  }

  attackEnemy(enemyName, damage) {
    const attackResult = this.combat.attack(enemyName, damage);
    if (attackResult) {
      console.log(`${attackResult.target} takes ${attackResult.damage} damage.`);
      const enemy = this.combat.enemies.find(e => e.name === attackResult.target);
      if (enemy.health <= 0) {
        console.log(`${attackResult.target} is defeated.`);
        const loot = this.loot.dropLoot();
        if (loot) {
          console.log(`You found ${loot}!`);
        }
      }
    }
  }

  playerTakeDamage(amount) {
    const healthResult = this.health.takeDamage(amount);
    console.log(`Player takes ${amount} damage. Health: ${healthResult.health}`);
  }

  playerHeal(amount) {
    const healthResult = this.health.heal(amount);
    console.log(`Player heals ${amount}. Health: ${healthResult.health}`);
  }
}

// Demo
const game = new GameCoordinator();
game.attackEnemy('Goblin', 20); // Goblin takes 20 damage.
game.playerTakeDamage(10); // Player takes 10 damage. Health: 90
game.playerHeal(20); // Player heals 20. Health: 100
game.attackEnemy('Goblin', 50); // Goblin is defeated. You found Potion of Healing!
