const DIFFICULTY_INCREASE = 1; // enemies to add every interval

// HTML5 Canvas setup
const canvas = document.createElement('canvas');
canvas.width = CANVAS_WIDTH;
canvas.height = CANVAS_HEIGHT;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

// Room layout
const room = [];
for (let y = 0; y < ROOM_HEIGHT; y++) {
    room[y] = [];
    for (let x = 0; x < ROOM_WIDTH; x++) {
        room[y][x] = (Math.random() < 0.7) ? 'floor' : 'wall';
    }
}

// Player
const player = {
    x: ROOM_WIDTH / 2,
    y: ROOM_HEIGHT / 2,
    render: function() {
        ctx.fillStyle = 'blue';
        ctx.fillRect(this.x * TILE_SIZE, this.y * TILE_SIZE, TILE_SIZE, TILE_SIZE);
    }
};

// Enemies
const enemies = [];
function spawnEnemy() {
    let enemy;
    do {
        enemy = {
            x: Math.floor(Math.random() * ROOM_WIDTH),
            y: Math.floor(Math.random() * ROOM_HEIGHT),
            render: function() {
                ctx.fillStyle = 'red';
                ctx.fillRect(this.x * TILE_SIZE, this.y * TILE_SIZE, TILE_SIZE, TILE_SIZE);
            }
        };
    } while (room[enemy.y][enemy.x] === 'wall');
    enemies.push(enemy);
}

// Game loop
let enemySpawnIntervalId;
let enemyCount = INITIAL_ENEMY_COUNT;

function gameLoop() {
    ctx.clearRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    // Render room
    for (let y = 0; y < ROOM_HEIGHT; y++) {
        for (let x = 0; x < ROOM_WIDTH; x++) {
            if (room[y][x] === 'wall') {
                ctx.fillStyle = 'grey';
            } else {
                ctx.fillStyle = 'lightgrey';
            }
            ctx.fillRect(x * TILE_SIZE, y * TILE_SIZE, TILE_SIZE, TILE_SIZE);
        }
    }

    // Render player
    player.render();

    // Render enemies
    enemies.forEach(enemy => enemy.render());

    requestAnimationFrame(gameLoop);
}

// Enemy spawner
function spawnEnemies() {
    for (let i = 0; i < enemyCount; i++) {
        spawnEnemy();
    }
    enemyCount += DIFFICULTY_INCREASE;
}

// Start the game
enemySpawnIntervalId = setInterval(spawnEnemies, ENEMY_SPAWN_INTERVAL);
gameLoop();
