    this.events = {};
  }

  emit(eventName, data) {
    if (this.events[eventName]) {
      this.events[eventName].forEach(handler => handler(data));
    }
  }

  subscribe(eventName, handler) {
    if (!this.events[eventName]) {
      this.events[eventName] = [];
    }
    this.events[eventName].push(handler);
  }
}

class Recipe {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.recipes = {
      "wooden_pickaxe": { "wood": 3, "stick": 2 },
      "bread": { "wheat": 3 }
    };

    this.eventBus.subscribe("craft", this.handleCraft.bind(this));
  }

  handleCraft(itemName) {
    if (this.recipes[itemName]) {
      this.eventBus.emit("recipeFound", { item: itemName, ingredients: this.recipes[itemName] });
    } else {
      console.log(`Recipe for ${itemName} not found.`);
    }
  }
}

class Inventory {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.items = {
      "wood": 10,
      "stick": 5,
      "wheat": 8
    };

    this.eventBus.subscribe("recipeFound", this.handleRecipeFound.bind(this));
  }

  handleRecipeFound(data) {
    const { item, ingredients } = data;
    const canCraft = Object.keys(ingredients).every(ingredient => {
      return this.items[ingredient] >= ingredients[ingredient];
    });

    if (canCraft) {
      Object.keys(ingredients).forEach(ingredient => {
        this.items[ingredient] -= ingredients[ingredient];
      });
      this.eventBus.emit("itemCrafted", { item });
      console.log(`Crafted ${item}. Remaining items:`, this.items);
    } else {
      console.log(`Not enough resources to craft ${item}. Current inventory:`, this.items);
    }
  }
}

class Crafting {
  constructor(eventBus) {
    this.eventBus = eventBus;

    this.eventBus.subscribe("itemCrafted", this.handleItemCrafted.bind(this));
  }

  handleItemCrafted(data) {
    console.log(`Item crafted: ${data.item}`);
  }

  craft(itemName) {
    this.eventBus.emit("craft", itemName);
  }
}

