const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = 400;
canvas.height = 600;
const ctx = canvas.getContext('2d');

const blockWidth = 50;
const blockHeight = 20;
const enemyWidth = 30;
const enemyHeight = 30;
const enemySpawnRate = 1000; // milliseconds
const maxEnemies = 10;
const gravity = 0.5;
const blockSpeed = 3;
let score = 0;
let fallingBlocks = [];
let enemies = [];
let lastEnemySpawn = 0;

function getRandomInt(min, max) {
  return Math.floor(Math.random() * (max - min + 1)) + min;
}

function drawRect(x, y, width, height, color) {
  ctx.fillStyle = color;
  ctx.fillRect(x, y, width, height);
}

function updateBlocks() {
  fallingBlocks.forEach(block => {
    block.y += blockSpeed;
    if (block.y > canvas.height) {
      fallingBlocks.shift();
    }
  });
}

function updateEnemies() {
  if (Date.now() - lastEnemySpawn > enemySpawnRate) {
    enemies.push({
      x: getRandomInt(0, canvas.width - enemyWidth),
      y: -enemyHeight,
      speed: getRandomInt(1, 3)
    });
    lastEnemySpawn = Date.now();
  }

  enemies.forEach(enemy => {
    enemy.y += enemy.speed;
    if (enemy.y > canvas.height) {
      enemies.shift();
    }
  });
}

function drawBlocks() {
  fallingBlocks.forEach(block => {
    drawRect(block.x, block.y, blockWidth, blockHeight, 'blue');
  });
}

function drawEnemies() {
  enemies.forEach(enemy => {
    drawRect(enemy.x, enemy.y, enemyWidth, enemyHeight, 'red');
  });
}

function checkCollisions() {
  fallingBlocks.forEach(block => {
    enemies.forEach((enemy, enemyIndex) => {
      if (block.x < enemy.x + enemyWidth &&
          block.x + blockWidth > enemy.x &&
          block.y < enemy.y + enemyHeight &&
          block.y + blockHeight > enemy.y) {
        enemies.splice(enemyIndex, 1);
        score++;
      }
    });
  });
}

function gameLoop() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  updateBlocks();
  updateEnemies();
  drawBlocks();
  drawEnemies();
  checkCollisions();
  drawRect(10, 10, 50, 20, 'black');
  ctx.fillStyle = 'black';
  ctx.fillText(`Score: ${score}`, 20, 30);
  requestAnimationFrame(gameLoop);
}

function startGame() {
  for (let i = 0; i < 5; i++) {
    fallingBlocks.push({
      x: getRandomInt(0, canvas.width - blockWidth),
      y: getRandomInt(-500, -100)
    });
  }
  gameLoop();
}

startGame();
