class Trade {
  constructor(prices) {
    this.prices = prices;
  }

  getPrices() {
    return { ...this.prices };
  }

  sellItem(item) {
    if (this.prices[item]) {
      return this.prices[item];
    }
    return null; // Item not found
  }
}

class Reputation {
  constructor() {
    this.standing = {};
  }

  getStanding(faction) {
    return this.standing[faction] || 0;
  }

  adjustStanding(faction, amount) {
    if (!this.standing[faction]) {
      this.standing[faction] = 0;
    }
    this.standing[faction] += amount;
  }
}

class Faction {
  constructor(name) {
    this.name = name;
  }

  getName() {
    return this.name;
  }
}

class Economy {
  constructor() {
    this.inventory = {};
    this.balance = 1000; // Starting balance
  }

  getBalance() {
    return this.balance;
  }

  debit(amount) {
    if (this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }

  addItem(item) {
    if (!this.inventory[item]) {
      this.inventory[item] = 0;
    }
    this.inventory[item] += 1;
  }
}

class Store {
  constructor(trade, economy, reputation) {
    this.trade = trade;
    this.economy = economy;
    this.reputation = reputation;
  }

  purchaseItem(item) {
    const price = this.trade.sellItem(item);
    if (price !== null) {
      if (this.economy.debit(price)) {
        this.economy.addItem(item);
        this.reputation.adjustStanding('buyer', 1); // Adjust reputation for buyers
        console.log(`Purchased ${item} for ${price}. Remaining balance: ${this.economy.getBalance()}`);
      } else {
        console.log(`Insufficient funds to purchase ${item}.`);
      }
    } else {
      console.log(`Item ${item} not available for purchase.`);
    }
  }
}

