class Inventory {
    constructor() {
        this.items = {};
    }

    addItem(item, quantity = 1) {
        if (this.items[item]) {
            this.items[item] += quantity;
        } else {
            this.items[item] = quantity;
        }
    }

    removeItem(item, quantity = 1) {
        if (this.items[item]) {
            this.items[item] -= quantity;
            if (this.items[item] <= 0) {
                delete this.items[item];
            }
        }
    }

    hasItem(item, quantity = 1) {
        return (this.items[item] || 0) >= quantity;
    }

    getItemQuantity(item) {
        return this.items[item] || 0;
    }
}

class Recipe {
    constructor(name, ingredients) {
        this.name = name;
        this.ingredients = ingredients; // { item: quantity }
    }

    canCraft(inventory) {
        return Object.keys(this.ingredients).every(item => 
            inventory.hasItem(item, this.ingredients[item])
        );
    }
}

class Crafting {
    constructor(inventory) {
        this.inventory = inventory;
        this.recipes = [];
    }

    addRecipe(recipe) {
        this.recipes.push(recipe);
    }

    craft(recipeName) {
        const recipe = this.recipes.find(r => r.name === recipeName);
        if (recipe && recipe.canCraft(this.inventory)) {
            Object.keys(recipe.ingredients).forEach(item => 
                this.inventory.removeItem(item, recipe.ingredients[item])
            );
            const outputItem = recipeName; // Assuming the output item is the recipe name
            this.inventory.addItem(outputItem);
            return true;
        }
        return false;
    }
}

