class Building {
  constructor(name, resourceCost) {
    this.name = name;
    this.resourceCost = resourceCost;
  }

  build(economy) {
    if (economy.canAfford(this.resourceCost)) {
      economy.spendResources(this.resourceCost);
      console.log(`Building ${this.name} constructed.`);
      return true;
    } else {
      console.log(`Not enough resources to build ${this.name}.`);
      return false;
    }
  }
}

class Resource {
  constructor(name, amount) {
    this.name = name;
    this.amount = amount;
  }

  add(amount) {
    this.amount += amount;
    console.log(`Added ${amount} ${this.name}. Total: ${this.amount}.`);
  }

  spend(amount) {
    if (this.amount >= amount) {
      this.amount -= amount;
      console.log(`Spent ${amount} ${this.name}. Remaining: ${this.amount}.`);
      return true;
    } else {
      console.log(`Not enough ${this.name} to spend ${amount}.`);
      return false;
    }
  }
}

class Economy {
  constructor() {
    this.resources = {
      wood: new Resource('wood', 100),
      gold: new Resource('gold', 50)
    };
  }

  canAfford(cost) {
    for (const [resourceName, amount] of Object.entries(cost)) {
      if (!this.resources[resourceName] || this.resources[resourceName].amount < amount) {
        return false;
      }
    }
    return true;
  }

  spendResources(cost) {
    for (const [resourceName, amount] of Object.entries(cost)) {
      this.resources[resourceName].spend(amount);
    }
  }

  addResources(amounts) {
    for (const [resourceName, amount] of Object.entries(amounts)) {
      this.resources[resourceName].add(amount);
    }
  }
}

