const canvas = document.createElement('canvas');
canvas.width = 400;
canvas.height = 400;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const gridSize = 20;
const cellSize = canvas.width / gridSize;

let snake = [{ x: 10, y: 10 }];
let direction = { x: 0, y: 0 };
let food = { x: 15, y: 15 };
let gameOver = false;
let score = 0;

const getRandomPosition = () => ({
  x: Math.floor(Math.random() * gridSize),
  y: Math.floor(Math.random() * gridSize)
});

const drawCell = (cell, color) => {
  ctx.fillStyle = color;
  ctx.fillRect(cell.x * cellSize, cell.y * cellSize, cellSize, cellSize);
};

const drawSnake = () => snake.forEach(cell => drawCell(cell, 'green'));

const drawFood = () => drawCell(food, 'red');

const checkCollision = (head, array) => array.some(segment => segment.x === head.x && segment.y === head.y);

const moveSnake = () => {
  const head = { x: snake[0].x + direction.x, y: snake[0].y + direction.y };
  if (head.x < 0 || head.x >= gridSize || head.y < 0 || head.y >= gridSize || checkCollision(head, snake)) {
    gameOver = true;
    return;
  }
  snake.unshift(head);
  if (head.x === food.x && head.y === food.y) {
    score++;
    food = getRandomPosition();
  } else {
    snake.pop();
  }
};

const aiMove = () => {
  const head = snake[0];
  const foodDirection = { x: food.x - head.x, y: food.y - head.y };
  const possibleMoves = [
    { x: 0, y: 1 },  // Down
    { x: 0, y: -1 }, // Up
    { x: 1, y: 0 },  // Right
    { x: -1, y: 0 }  // Left
  ];
  possibleMoves.sort((a, b) => {
    const distanceA = Math.abs(foodDirection.x - a.x) + Math.abs(foodDirection.y - a.y);
    const distanceB = Math.abs(foodDirection.x - b.x) + Math.abs(foodDirection.y - b.y);
    return distanceA - distanceB;
  });
  const move = possibleMoves.find(move => !checkCollision({ x: head.x + move.x, y: head.y + move.y }, snake));
  direction = move || { x: 0, y: 0 };
};

const update = () => {
  if (gameOver) return;
  aiMove();
  moveSnake();
};

const render = () => {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  drawSnake();
  drawFood();
  ctx.fillStyle = 'black';
  ctx.fillText(`Score: ${score}`, 10, 20);
};

const gameLoop = timestamp => {
  const deltaTime = timestamp - lastTime;
  if (deltaTime >= 1000 / 10) {
    update();
    render();
    lastTime = timestamp;
  }
  if (!gameOver) requestAnimationFrame(gameLoop);
};

let lastTime = performance.now();
requestAnimationFrame(gameLoop);
