// Initialize canvas and context
const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

// Handle device pixel ratio for sharp rendering
const dpr = window.devicePixelRatio || 1;
canvas.width = window.innerWidth * dpr;
canvas.height = window.innerHeight * dpr;
ctx.scale(dpr, dpr);

// Game state
const state = {
  level: 1,
  fish: [],
  score: 0,
  gameSpeed: 1,
  waveInterval: 2000,
  nextWaveTime: Date.now() + 2000
};

// Fish object
function Fish(x, y, speed) {
  this.x = x;
  this.y = y;
  this.speed = speed;
  this.width = 20;
  this.height = 10;
}

Fish.prototype.draw = function() {
  ctx.fillStyle = 'blue';
  ctx.fillRect(this.x, this.y, this.width, this.height);
};

Fish.prototype.update = function() {
  this.x -= this.speed * state.gameSpeed;
};

// Handle window resize
window.addEventListener('resize', () => {
  canvas.width = window.innerWidth * dpr;
  canvas.height = window.innerHeight * dpr;
  ctx.scale(dpr, dpr);
});

// Handle mouse click
canvas.addEventListener('click', (event) => {
  const rect = canvas.getBoundingClientRect();
  const clickX = (event.clientX - rect.left) * dpr;
  const clickY = (event.clientY - rect.top) * dpr;

  state.fish.forEach((fish, index) => {
    if (
      clickX > fish.x &&
      clickX < fish.x + fish.width &&
      clickY > fish.y &&
      clickY < fish.y + fish.height
    ) {
      state.fish.splice(index, 1);
      state.score += 10;
    }
  });
});

// Spawn fish
function spawnFish() {
  const y = Math.random() * (canvas.height - 10);
  const speed = Math.random() * 2 + 1;
  state.fish.push(new Fish(canvas.width, y, speed));
}

// Update game state
function update() {
  const now = Date.now();
  if (now > state.nextWaveTime) {
    spawnFish();
    state.nextWaveTime = now + state.waveInterval / state.level;
    if (state.level % 5 === 0) {
      state.level++;
      state.gameSpeed += 0.1;
    }
  }

  state.fish.forEach((fish, index) => {
    fish.update();
    if (fish.x + fish.width < 0) {
      state.fish.splice(index, 1);
    }
  });
}

// Render game
function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  state.fish.forEach(fish => fish.draw());

  ctx.fillStyle = 'black';
  ctx.fillText(`Score: ${state.score}`, 10, 20);
  ctx.fillText(`Level: ${state.level}`, 10, 40);
}

// Game loop
function gameLoop() {
  update();
  render();
  requestAnimationFrame(gameLoop);
}

// Start game loop
gameLoop();
