// Event Bus implementation
class EventBus {
  constructor() {
    this.events = {};
  }

  subscribe(event, listener) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(listener);
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(listener => listener(data));
    }
  }
}

// Skill System
class Skill {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.skills = {};
    this.eventBus.subscribe('levelUp', this.onLevelUp.bind(this));
  }

  learnSkill(skillName, description) {
    this.skills[skillName] = description;
    console.log(`Learned skill: ${skillName}`);
    this.eventBus.emit('skillLearned', { skillName });
  }

  onLevelUp(level) {
    console.log(`Level up to level ${level}! Learning new skills...`);
    if (level === 2) {
      this.learnSkill('Advanced Skill', 'A powerful advanced skill');
    } else if (level === 3) {
      this.learnSkill('Expert Skill', 'An expert-level skill');
    }
  }
}

// Experience System
class Experience {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.experiencePoints = 0;
    this.eventBus.subscribe('skillLearned', this.onSkillLearned.bind(this));
  }

  gainExperience(points) {
    this.experiencePoints += points;
    console.log(`Gained ${points} experience points. Total: ${this.experiencePoints}`);
    if (this.experiencePoints >= 100) {
      this.levelUp();
    }
  }

  levelUp() {
    const newLevel = Math.floor(this.experiencePoints / 100) + 1;
    console.log(`Leveling up to level ${newLevel}!`);
    this.eventBus.emit('levelUp', newLevel);
  }

  onSkillLearned({ skillName }) {
    console.log(`Skill ${skillName} learned. Gaining experience...`);
    this.gainExperience(20);
  }
}

// LevelUp System
