class Economy {
    constructor(prices) {
        this.prices = prices;
    }

    getPrice(item) {
        return this.prices[item] || null;
    }

    debit(item, amount) {
        if (this.prices[item] >= amount) {
            this.prices[item] -= amount;
            return true;
        }
        return false;
    }
}

class Inventory {
    constructor() {
        this.items = {};
    }

    addItem(item, amount) {
        if (this.items[item]) {
            this.items[item] += amount;
        } else {
            this.items[item] = amount;
        }
    }

    getInventory() {
        return this.items;
    }
}

class Store {
    constructor(economy, inventory) {
        this.economy = economy;
        this.inventory = inventory;
    }

    purchase(item, amount) {
        const price = this.economy.getPrice(item);
        if (price !== null && this.economy.debit(item, price * amount)) {
            this.inventory.addItem(item, amount);
            return true;
        }
        return false;
    }
}

class Reputation {
    constructor() {
        this.standing = 0;
    }

    increaseStanding(amount) {
        this.standing += amount;
    }

    decreaseStanding(amount) {
        this.standing -= amount;
    }

    getStanding() {
        return this.standing;
    }
}

class Faction {
    constructor(name) {
        this.name = name;
        this.reputation = new Reputation();
    }

    improveReputation(amount) {
        this.reputation.increaseStanding(amount);
    }

    damageReputation(amount) {
        this.reputation.decreaseStanding(amount);
    }

    getReputation() {
        return this.reputation.getStanding();
    }
}

