class Example extends Phaser.Scene
{
    constructor ()
    {
        super();
    }

    preload ()
    {
        // this.load.setBaseURL('https://cdn.phaserfiles.com/v385');
        this.load.image('coffee', 'assets/sprites/coffee.png');
        this.load.image('donut', 'assets/sprites/donut.png');
