const scoreIncrement = 10;

let playerX = 50;
let playerY = canvas.height - playerHeight - 50;
let playerVelocity = 0;
let obstacles = [];
let score = 0;
let gameOver = false;

const fixedTimeStep = 1000 / 60;
let lastTime = 0;

function update(deltaTime) {
  if (!gameOver) {
    playerVelocity += gravity * deltaTime;
    playerY += playerVelocity * deltaTime;

    if (playerY + playerHeight > canvas.height) {
      playerY = canvas.height - playerHeight;
      playerVelocity = 0;
    }

    for (let i = 0; i < obstacles.length; i++) {
      obstacles[i].x -= obstacleSpeed * deltaTime;
      if (obstacles[i].x + obstacleWidth < 0) {
        obstacles.splice(i, 1);
        score += scoreIncrement;
        break;
      }
    }
  }
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  ctx.fillStyle = 'green';
  ctx.fillRect(0, canvas.height - playerHeight - 50, canvas.width, 50);

  ctx.fillStyle = 'blue';
  ctx.fillRect(playerX, playerY, playerWidth, playerHeight);

  ctx.fillStyle = 'red';
  for (let obstacle of obstacles) {
    ctx.fillRect(obstacle.x, obstacle.y, obstacleWidth, obstacleHeight);
  }

  ctx.fillStyle = 'black';
  ctx.font = '30px Arial';
  ctx.fillText('Score: ' + score, 10, 50);

  if (gameOver) {
    ctx.fillStyle = 'red';
    ctx.font = '50px Arial';
    ctx.fillText('Game Over', canvas.width / 2 - 150, canvas.height / 2);
  }
}

function checkCollisions() {
  for (let obstacle of obstacles) {
    if (
      playerX < obstacle.x + obstacleWidth &&
      playerX + playerWidth > obstacle.x &&
      playerY < obstacle.y + obstacleHeight &&
      playerY + playerHeight > obstacle.y
    ) {
      gameOver = true;
    }
  }
}

function gameLoop(timestamp) {
  const deltaTime = timestamp - lastTime;
  lastTime = timestamp;

  update(deltaTime);
  checkCollisions();
  draw();

  requestAnimationFrame(gameLoop);
}

document.addEventListener('click', function() {
  if (!gameOver) {
    playerVelocity = jumpPower;
  }
});

obstacles.push({ x: canvas.width, y: canvas.height - obstacleHeight - 50 });
obstacles.push({ x: canvas.width + 200, y: canvas.height - obstacleHeight - 50 });

requestAnimationFrame(gameLoop);
