    return this.balance;
  }

  addFunds(amount) {
    this.balance += amount;
  }

  subtractFunds(amount) {
    if (this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }
}

class Store {
  constructor(prices) {
    this.prices = prices; // Prices of items
  }

  getPrices() {
    return { ...this.prices };
  }

  getItemPrice(item) {
    return this.prices[item] || null;
  }
}

class Inventory {
  constructor() {
    this.items = {}; // Inventory of items
  }

  addItem(item, quantity) {
    if (this.items[item]) {
      this.items[item] += quantity;
    } else {
      this.items[item] = quantity;
    }
  }

  getItemCount(item) {
    return this.items[item] || 0;
  }

  removeItem(item, quantity) {
    if (this.items[item] && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      return true;
    }
    return false;
  }
}

class GameCoordinator {
  constructor() {
    this.economy = new Economy();
    this.store = new Store({ apple: 10, banana: 5 });
    this.inventory = new Inventory();
  }

  buyItem(item, quantity) {
    const price = this.store.getItemPrice(item);
    if (price !== null) {
      const totalCost = price * quantity;
      if (this.economy.subtractFunds(totalCost)) {
        this.inventory.addItem(item, quantity);
        console.log(`Bought ${quantity} ${item}(s).`);
      } else {
        console.log(`Not enough funds to buy ${quantity} ${item}(s).`);
      }
    } else {
      console.log(`Item ${item} not available in store.`);
    }
  }

  sellItem(item, quantity) {
    if (this.inventory.removeItem(item, quantity)) {
      const price = this.store.getItemPrice(item);
      const totalEarnings = price * quantity;
      this.economy.addFunds(totalEarnings);
      console.log(`Sold ${quantity} ${item}(s).`);
    } else {
      console.log(`Not enough ${item}(s) in inventory to sell.`);
    }
  }

  displayStatus() {
