const canvas = document.createElement('canvas');
canvas.width = 400;
canvas.height = 400;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const tileMap = new Array(16).fill(0);
let score = 0;
let gameOver = false;

function drawTile(x, y, value) {
    ctx.fillStyle = value === 0 ? '#ccc' : `hsl(${20 * Math.log2(value)}, 100%, 50%)`;
    ctx.fillRect(x * 100, y * 100, 100, 100);
    ctx.fillStyle = '#fff';
    ctx.font = '50px Arial';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    if (value !== 0) ctx.fillText(value.toString(), x * 100 + 50, y * 100 + 50);
}

function drawBoard() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    for (let i = 0; i < 16; i++) {
        drawTile(i % 4, Math.floor(i / 4), tileMap[i]);
    }
    ctx.fillStyle = '#000';
    ctx.font = '20px Arial';
    ctx.fillText(`Score: ${score}`, 320, 40);
}

function spawnTile() {
    const emptyTiles = tileMap.reduce((acc, val, i) => val === 0 ? acc.concat(i) : acc, []);
    if (emptyTiles.length === 0) {
        gameOver = true;
        return;
    }
    const randomIndex = Math.floor(Math.random() * emptyTiles.length);
    tileMap[emptyTiles[randomIndex]] = Math.random() < 0.9 ? 2 : 4;
}

function slide(direction) {
    const moves = {
        up: (i) => i - 4,
        down: (i) => i + 4,
        left: (i) => i - 1,
        right: (i) => i + 1
    };
    const [start, end, step] = direction === 'up' || direction === 'left' ? [0, 16, 1] : [15, -1, -1];
    const merged = new Array(16).fill(false);

    for (let i = start; direction === 'up' || direction === 'down' ? i < end : i > end; i += step) {
        if (i % 4 === 3 && direction === 'left') continue;
        if (i % 4 === 0 && direction === 'right') continue;
        if (tileMap[i] === 0) continue;

        let target = i;
        while (target + moves[direction] >= 0 && target + moves[direction] < 16 && tileMap[target + moves[direction]] === 0) {
            target += moves[direction];
        }

        if (target !== i && tileMap[target] === tileMap[i] && !merged[target]) {
            tileMap[target] *= 2;
            score += tileMap[target];
            tileMap[i] = 0;
            merged[target] = true;
        } else if (target !== i) {
            tileMap[target] = tileMap[i];
            tileMap[i] = 0;
        }
    }
}

function gameTick() {
    if (gameOver) return;
    slide(directions[Math.floor(Math.random() * 4)]);
    spawnTile();
    drawBoard();
    requestAnimationFrame(gameTick);
}

const directions = ['up', 'down', 'left', 'right'];
spawnTile();
spawnTile();
drawBoard();
requestAnimationFrame(gameTick);
