class EventBus {
  constructor() {
    this.events = {};
  }

  subscribe(event, callback) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(callback);
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(callback => callback(data));
    }
  }
}

class Inventory {
  constructor(eventBus) {
    this.items = {};
    this.eventBus = eventBus;
    this.eventBus.subscribe('itemAdded', this.handleItemAdded.bind(this));
  }

  addItem(item, quantity) {
    if (!this.items[item]) {
      this.items[item] = 0;
    }
    this.items[item] += quantity;
    this.eventBus.emit('inventoryUpdated', { item, quantity });
  }

  useItem(item, quantity) {
    if (this.items[item] >= quantity) {
      this.items[item] -= quantity;
      this.eventBus.emit('inventoryUpdated', { item, quantity });
      return true;
    }
    return false;
  }

  handleItemAdded(event) {
    this.addItem(event.item, event.quantity);
  }
}

class Recipe {
  constructor(eventBus) {
    this.recipes = {};
    this.eventBus = eventBus;
    this.eventBus.subscribe('recipeNeeded', this.handleRecipeNeeded.bind(this));
  }

  addRecipe(recipeName, ingredients) {
    this.recipes[recipeName] = ingredients;
  }

  craft(recipeName) {
    const ingredients = this.recipes[recipeName];
    if (ingredients) {
      for (const [item, quantity] of Object.entries(ingredients)) {
        if (!this.eventBus.emit('useItem', { item, quantity })) {
          console.log(`Not enough ${item} to craft ${recipeName}`);
          return false;
        }
      }
      this.eventBus.emit('craftSuccess', { recipeName });
      return true;
    }
    console.log(`Recipe ${recipeName} not found`);
    return false;
  }

  handleRecipeNeeded(event) {
    this.craft(event.recipeName);
  }
}

class Crafting {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('craftSuccess', this.handleCraftSuccess.bind(this));
  }

  requestCraft(recipeName) {
    this.eventBus.emit('recipeNeeded', { recipeName });
  }

  handleCraftSuccess(event) {
    console.log(`Successfully crafted ${event.recipeName}`);
  }
}

