class EventBus {
  constructor() {
    this.listeners = {};
  }

  subscribe(event, callback) {
    if (!this.listeners[event]) {
      this.listeners[event] = [];
    }
    this.listeners[event].push(callback);
  }

  emit(event, data) {
    if (this.listeners[event]) {
      this.listeners[event].forEach(callback => callback(data));
    }
  }
}

// Bank system
class Bank {
  constructor(eventBus) {
    this.balance = 0;
    this.eventBus = eventBus;
    this.eventBus.subscribe('deposit', this.deposit.bind(this));
    this.eventBus.subscribe('withdraw', this.withdraw.bind(this));
  }

  deposit(amount) {
    this.balance += amount;
    console.log(`Deposited ${amount}. New balance: ${this.balance}`);
    this.eventBus.emit('balanceUpdated', { balance: this.balance });
  }

  withdraw(amount) {
    if (this.balance >= amount) {
      this.balance -= amount;
      console.log(`Withdrew ${amount}. New balance: ${this.balance}`);
      this.eventBus.emit('balanceUpdated', { balance: this.balance });
    } else {
      console.log('Insufficient funds.');
    }
  }
}

// Market system
class Market {
  constructor(eventBus) {
    this.prices = { apple: 1, banana: 2, orange: 3 };
    this.eventBus = eventBus;
    this.eventBus.subscribe('buy', this.buy.bind(this));
  }

  buy(item, quantity) {
    const price = this.prices[item];
    if (price) {
      const totalCost = price * quantity;
      this.eventBus.emit('withdraw', totalCost);
      this.eventBus.subscribe('balanceUpdated', ({ balance }) => {
        if (balance >= totalCost) {
          console.log(`Bought ${quantity} ${item}(s).`);
          this.eventBus.emit('addToInventory', { item, quantity });
        } else {
          console.log('Transaction failed: Insufficient balance.');
        }
      }, { once: true });
    } else {
      console.log('Item not available in market.');
    }
  }
}

// Inventory system
class Inventory {
  constructor(eventBus) {
    this.items = {};
    this.eventBus = eventBus;
    this.eventBus.subscribe('addToInventory', this.addToInventory.bind(this));
  }

  addToInventory({ item, quantity }) {
    if (this.items[item]) {
      this.items[item] += quantity;
    } else {
      this.items[item] = quantity;
    }
    console.log(`Inventory updated: ${item} - ${this.items[item]}`);
  }
}

