class Wallet {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.balance = 0;
    this.eventBus.subscribe('buyItem', this.handleBuyItem.bind(this));
  }

  deposit(amount) {
    this.balance += amount;
    console.log(`Deposited: ${amount}, New Balance: ${this.balance}`);
  }

  withdraw(amount) {
    if (amount > this.balance) {
      console.log('Insufficient funds');
      return false;
    }
    this.balance -= amount;
    console.log(`Withdrew: ${amount}, New Balance: ${this.balance}`);
    return true;
  }

  handleBuyItem({ price }) {
    if (this.withdraw(price)) {
      this.eventBus.emit('itemBought', { price });
    }
  }
}

