const canvas = document.createElement('canvas');
const ctx = canvas.getContext('2d');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);

const gravity = 0.5;
const jumpVelocity = -10;
const playerWidth = 50;
const playerHeight = 50;
const platformHeight = 20;
const platformWidth = 200;
const platformGap = 300;
const aiSpeed = 2;
const playerSpeed = 5;
const fixedTimestep = 1000 / 60;
let lastTime = performance.now();

const player = {
  x: 100,
  y: canvas.height - playerHeight - platformHeight,
  velocityY: 0,
  isJumping: false
};

const ai = {
  x: 700,
  y: canvas.height - playerHeight - platformHeight,
  velocityY: 0,
  isJumping: false
};

const platforms = [
  { x: 0, y: canvas.height - platformHeight, width: canvas.width, height: platformHeight },
  { x: 200, y: canvas.height - 200 - platformHeight, width: platformWidth, height: platformHeight },
  { x: 400, y: canvas.height - 400 - platformHeight, width: platformWidth, height: platformHeight }
];

function updatePlayerInput() {
  if (keys['ArrowLeft'] && player.x > 0) {
    player.x -= playerSpeed;
  }
  if (keys['ArrowRight'] && player.x < canvas.width - playerWidth) {
    player.x += playerSpeed;
  }
  if (keys['ArrowUp'] && !player.isJumping) {
    player.velocityY = jumpVelocity;
    player.isJumping = true;
  }
}

function updateAI() {
  if (player.x < ai.x) {
    ai.x -= aiSpeed;
  } else if (player.x > ai.x) {
    ai.x += aiSpeed;
  }
  if (ai.y > player.y && !ai.isJumping) {
    ai.velocityY = jumpVelocity;
    ai.isJumping = true;
  }
}

function updatePhysics(entity, platforms) {
  entity.velocityY += gravity;
  entity.y += entity.velocityY;

  for (const platform of platforms) {
    if (entity.y + entity.height >= platform.y &&
        entity.x + entity.width > platform.x &&
        entity.x < platform.x + platform.width) {
      entity.y = platform.y - entity.height;
      entity.velocityY = 0;
      entity.isJumping = false;
      break;
    }
  }
}

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  ctx.fillStyle = 'green';
  platforms.forEach(platform => {
    ctx.fillRect(platform.x, platform.y, platform.width, platform.height);
  });

  ctx.fillStyle = 'blue';
  ctx.fillRect(player.x, player.y, playerWidth, playerHeight);

  ctx.fillStyle = 'red';
  ctx.fillRect(ai.x, ai.y, playerWidth, playerHeight);
}

function gameLoop(timestamp) {
  const deltaTime = timestamp - lastTime;
  lastTime = timestamp;

  updatePlayerInput();
  updatePhysics(player, platforms);
  updateAI();
  updatePhysics(ai, platforms);

  render();

  requestAnimationFrame(gameLoop);
}

const keys = {};
window.addEventListener('keydown', (e) => keys[e.key] = true);
window.addEventListener('keyup', (e) => keys[e.key] = false);

requestAnimationFrame(gameLoop);
