const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = window.innerWidth;
canvas.height = window.innerHeight;
const ctx = canvas.getContext('2d');

const ship = {
  x: canvas.width / 2,
  y: canvas.height / 2,
  r: 10,
  a: 0,
  thrust: 0,
  vx: 0,
  vy: 0,
  maxThrust: 0.2,
  maxSpeed: 5,
  turnSpeed: 0.05
};

const asteroids = [];
const numAsteroids = 10;

for (let i = 0; i < numAsteroids; i++) {
  asteroids.push({
    x: Math.random() * canvas.width,
    y: Math.random() * canvas.height,
    r: 15 + Math.random() * 20,
    a: Math.random() * Math.PI * 2,
    vx: (Math.random() - 0.5) * 2,
    vy: (Math.random() - 0.5) * 2
  });
}

function drawShip() {
  ctx.save();
  ctx.translate(ship.x, ship.y);
  ctx.rotate(ship.a);
  ctx.beginPath();
  ctx.moveTo(0, -ship.r);
  ctx.lineTo(ship.r, ship.r);
  ctx.lineTo(-ship.r, ship.r);
  ctx.closePath();
  ctx.fillStyle = 'white';
  ctx.fill();
  ctx.restore();
}

function drawAsteroids() {
  ctx.fillStyle = 'gray';
  asteroids.forEach(asteroid => {
    ctx.beginPath();
    ctx.arc(asteroid.x, asteroid.y, asteroid.r, 0, Math.PI * 2);
    ctx.fill();
  });
}

function updateShip() {
  if (ship.thrust) {
    ship.vx += Math.cos(ship.a) * ship.thrust;
    ship.vy += Math.sin(ship.a) * ship.thrust;
  }
  ship.vx = Math.min(Math.max(ship.vx, -ship.maxSpeed), ship.maxSpeed);
  ship.vy = Math.min(Math.max(ship.vy, -ship.maxSpeed), ship.maxSpeed);
  ship.x += ship.vx;
  ship.y += ship.vy;
  if (ship.x < 0) ship.x = canvas.width;
  if (ship.x > canvas.width) ship.x = 0;
  if (ship.y < 0) ship.y = canvas.height;
  if (ship.y > canvas.height) ship.y = 0;
}

function updateAsteroids() {
  asteroids.forEach(asteroid => {
    asteroid.x += asteroid.vx;
    asteroid.y += asteroid.vy;
    if (asteroid.x < 0) asteroid.x = canvas.width;
    if (asteroid.x > canvas.width) asteroid.x = 0;
    if (asteroid.y < 0) asteroid.y = canvas.height;
    if (asteroid.y > canvas.height) asteroid.y = 0;
  });
}

function gameLoop() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  updateShip();
  updateAsteroids();
  drawAsteroids();
  drawShip();
  requestAnimationFrame(gameLoop);
}

document.addEventListener('keydown', e => {
  switch (e.key) {
    case 'ArrowUp':
      ship.thrust = Math.min(ship.thrust + ship.maxThrust, ship.maxThrust);
      break;
    case 'ArrowLeft':
      ship.a -= ship.turnSpeed;
      break;
    case 'ArrowRight':
      ship.a += ship.turnSpeed;
      break;
  }
});

document.addEventListener('keyup', e => {
  if (e.key === 'ArrowUp') ship.thrust = 0;
});

canvas.addEventListener('mousemove', e => {
  const mx = e.clientX;
  const my = e.clientY;
  ship.a = Math.atan2(my - ship.y, mx - ship.x);
});

canvas.addEventListener('click', e => {
  ship.thrust = ship.maxThrust;
});

requestAnimationFrame(gameLoop);
