    }

    isBuilt() {
        return this.isConstructed;
    }
}

// Resource System
class Resource {
    constructor(type, amount) {
        this.type = type;
        this.amount = amount;
    }

    add(amount) {
        this.amount += amount;
        console.log(`Added ${amount} ${this.type}. Total: ${this.amount}.`);
    }

    remove(amount) {
        if (this.amount >= amount) {
            this.amount -= amount;
            console.log(`Removed ${amount} ${this.type}. Remaining: ${this.amount}.`);
            return true;
        } else {
            console.log(`Not enough ${this.type} to remove.`);
            return false;
        }
    }

    getAmount() {
        return this.amount;
    }
}

// Economy System
class Economy {
    constructor(resources) {
        this.resources = resources; // Array of Resource objects
    }

    hasResources(costs) {
        for (let resourceType in costs) {
            const resource = this.resources.find(r => r.type === resourceType);
            if (!resource || resource.getAmount() < costs[resourceType]) {
                return false;
            }
        }
        return true;
    }

    spendResources(costs) {
        for (let resourceType in costs) {
            const resource = this.resources.find(r => r.type === resourceType);
            if (resource) {
                resource.remove(costs[resourceType]);
            }
        }
    }

    addResource(type, amount) {
        let resource = this.resources.find(r => r.type === type);
        if (resource) {
            resource.add(amount);
        } else {
            resource = new Resource(type, amount);
            this.resources.push(resource);
        }
    }
}

// Demo
const wood = new Resource('Wood', 50);
const stone = new Resource('Stone', 30);
const economy = new Economy([wood, stone]);

const house = new Building('House', { Wood: 30, Stone: 10 });
const castle = new Building('Castle', { Wood: 50, Stone: 50 });

house.construct(economy);
console.log(`House built: ${house.isBuilt()}`);

castle.construct(economy);
console.log(`Castle built: ${castle.isBuilt()}`);

economy.addResource('Wood', 20);
console.log('Added more wood.');

house.construct(economy);
console.log(`House built: ${house.isBuilt()}`);

castle.construct(economy);
console.log(`Castle built: ${castle.isBuilt()}`);
