class Skill {
    constructor(name, initialLevel = 1) {
        this.name = name;
        this.level = initialLevel;
    }

    getName() {
        return this.name;
    }

    getLevel() {
        return this.level;
    }

    increaseLevel() {
        this.level++;
    }
}

class Experience {
    constructor(base = 0) {
        this.baseExperience = base;
        this.currentExperience = base;
    }

    getExperience() {
        return this.currentExperience;
    }

    addExperience(amount) {
        this.currentExperience += amount;
    }

    resetExperience() {
        this.currentExperience = this.baseExperience;
    }
}

class LevelUp {
    constructor(requiredExperiencePerLevel = 100) {
        this.requiredExperiencePerLevel = requiredExperiencePerLevel;
        this.currentLevel = 1;
    }

    getLevel() {
        return this.currentLevel;
    }

    setLevel(level) {
        this.currentLevel = level;
    }

    levelUp() {
        this.currentLevel++;
    }

    checkLevelUp(experience) {
        const levels = Math.floor(experience / this.requiredExperiencePerLevel);
        if (levels > 0) {
            this.setLevel(this.currentLevel + levels);
            return true;
        }
        return false;
    }
}

class GameCoordinator {
    constructor(skillName, baseExperience = 0, requiredExperiencePerLevel = 100) {
        this.skill = new Skill(skillName);
        this.experience = new Experience(baseExperience);
        this.levelUp = new LevelUp(requiredExperiencePerLevel);
    }

    getSkillName() {
        return this.skill.getName();
    }

    getSkillLevel() {
        return this.skill.getLevel();
    }

    getExperience() {
        return this.experience.getExperience();
    }

    getLevel() {
        return this.levelUp.getLevel();
    }

    addExperience(amount) {
        this.experience.addExperience(amount);
        if (this.levelUp.checkLevelUp(this.experience.getExperience())) {
            this.skill.increaseLevel();
            this.experience.resetExperience();
        }
    }
}

