// Constants
const CANVAS_WIDTH = 800;
const CANVAS_HEIGHT = 600;
const PLAYER_SIZE = 30;
const GAP_SIZE = 150;
const PIPE_WIDTH = 70;
const PIPE_SPEED = 4;
const GRAVITY = 0.5;
const JUMP_STRENGTH = -10;
const HEALTH_DECREMENT = 1;
const INITIAL_HEALTH = 5;

// Global variables
let canvas, ctx;
let player = { x: 50, y: CANVAS_HEIGHT / 2, vy: 0 };
let pipes = [];
let health = INITIAL_HEALTH;
let gameRunning = true;

// Initialize canvas and context
function init() {
    canvas = document.createElement('canvas');
    canvas.width = CANVAS_WIDTH;
    canvas.height = CANVAS_HEIGHT;
    document.body.appendChild(canvas);
    ctx = canvas.getContext('2d');
}

// Update game state
function update() {
    if (!gameRunning) return;

    // Move player
    player.vy += GRAVITY;
    player.y += player.vy;

    // Jump on spacebar press
    if (keys[' ']) {
        player.vy = JUMP_STRENGTH;
        keys[' '] = false;
    }

    // Check for collision with ground
    if (player.y + PLAYER_SIZE > CANVAS_HEIGHT) {
        player.y = CANVAS_HEIGHT - PLAYER_SIZE;
        player.vy = 0;
        health -= HEALTH_DECREMENT;
        if (health <= 0) {
            respawn();
        }
    }

    // Move pipes
    pipes.forEach(pipe => {
        pipe.x -= PIPE_SPEED;
    });

    // Remove off-screen pipes
    pipes = pipes.filter(pipe => pipe.x + PIPE_WIDTH > 0);

    // Generate new pipes
    if (pipes.length === 0 || pipes[pipes.length - 1].x < CANVAS_WIDTH - 300) {
        const gapY = Math.random() * (CANVAS_HEIGHT - GAP_SIZE);
        pipes.push({ x: CANVAS_WIDTH, y: 0, height: gapY });
        pipes.push({ x: CANVAS_WIDTH, y: gapY + GAP_SIZE, height: CANVAS_HEIGHT - (gapY + GAP_SIZE) });
    }

    // Check for collision with pipes
    pipes.forEach(pipe => {
        if (player.x < pipe.x + PIPE_WIDTH &&
            player.x + PLAYER_SIZE > pipe.x &&
            player.y < pipe.y + pipe.height) {
            health -= HEALTH_DECREMENT;
            if (health <= 0) {
                respawn();
            }
        }
    });
}

// Render game
function render() {
    ctx.clearRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    // Draw player
    ctx.fillStyle = 'blue';
    ctx.fillRect(player.x, player.y, PLAYER_SIZE, PLAYER_SIZE);

    // Draw pipes
    ctx.fillStyle = 'green';
    pipes.forEach(pipe => {
        ctx.fillRect(pipe.x, pipe.y, PIPE_WIDTH, pipe.height);
    });

    // Draw health bar
    ctx.fillStyle = 'red';
    ctx.fillRect(10, 10, health * 20, 20);
}

// Respawn player
function respawn() {
    player = { x: 50, y: CANVAS_HEIGHT / 2, vy: 0 };
    health = INITIAL_HEALTH;
}

// Handle key presses
const keys = {};
window.addEventListener('keydown', (e) => {
    keys[e.key] = true;
});
window.addEventListener('keyup', (e) => {
    keys[e.key] = false;
});

// Game loop
function gameLoop() {
    update();
    render();
    requestAnimationFrame(gameLoop);
}

// Start the game
init();
gameLoop();
