// Constants
const GROUND_Y = 0.75;
const PARTICLE_COUNT = 50;
const GRAVITY = 0.5;
const JUMP_STRENGTH = -10;
const PLAYER_SPEED = 5;
const KEY_LEFT = 37;
const KEY_RIGHT = 39;
const KEY_SPACE = 32;

// Canvas setup
const canvas = document.createElement('canvas');
const ctx = canvas.getContext('2d');
document.body.appendChild(canvas);
resizeCanvas();

function resizeCanvas() {
    canvas.width = window.innerWidth * devicePixelRatio;
    canvas.height = window.innerHeight * devicePixelRatio;
    ctx.scale(devicePixelRatio, devicePixelRatio);
}

window.addEventListener('resize', resizeCanvas);

// Player setup
const player = {
    x: 50,
    y: GROUND_Y,
    width: 30,
    height: 50,
    velocity: { x: 0, y: 0 },
    isJumping: false
};

// Input handling
const keys = {};
window.addEventListener('keydown', (e) => keys[e.keyCode] = true);
window.addEventListener('keyup', (e) => keys[e.keyCode] = false);

// Particle system
const particles = [];

function createParticle(x, y) {
    particles.push({
        x: x,
        y: y,
        size: Math.random() * 3 + 1,
        velocity: {
            x: (Math.random() - 0.5) * 5,
            y: -Math.random() * 5
        },
        life: Math.random() * 50 + 50
    });
}

function updateParticles() {
    particles.forEach((particle, index) => {
        particle.x += particle.velocity.x;
        particle.y += particle.velocity.y;
        particle.life -= 1;
        if (particle.life <= 0) {
            particles.splice(index, 1);
        }
    });
}

function drawParticles() {
    ctx.fillStyle = 'rgba(255, 255, 255, 0.5)';
    particles.forEach(particle => {
        ctx.beginPath();
        ctx.arc(particle.x, particle.y, particle.size, 0, Math.PI * 2);
        ctx.fill();
    });
}

// Game loop
function gameLoop() {
    updatePlayer();
    updateParticles();
    render();
    requestAnimationFrame(gameLoop);
}

function updatePlayer() {
    const { x, y, width, height, velocity } = player;

    // Movement
    if (keys[KEY_LEFT]) player.velocity.x = -PLAYER_SPEED;
    else if (keys[KEY_RIGHT]) player.velocity.x = PLAYER_SPEED;
    else player.velocity.x = 0;

    // Gravity
    player.velocity.y += GRAVITY;
    player.y += player.velocity.y;

    // Jumping
    if (keys[KEY_SPACE] && !player.isJumping) {
        player.velocity.y = JUMP_STRENGTH;
        player.isJumping = true;
        createParticle(x + width / 2, y);
    }

    // Ground collision
    if (player.y + height >= canvas.height * GROUND_Y) {
        player.y = canvas.height * GROUND_Y - height;
        player.velocity.y = 0;
        player.isJumping = false;
    }
}

function render() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw ground
    ctx.fillStyle = 'green';
    ctx.fillRect(0, canvas.height * GROUND_Y, canvas.width, canvas.height);

    // Draw player
    ctx.fillStyle = 'blue';
    ctx.fillRect(player.x, player.y, player.width, player.height);

    // Draw particles
    drawParticles();
}

// Start game loop
requestAnimationFrame(gameLoop);
