class EventBus {
  constructor() {
    this.events = {};
  }

  subscribe(event, listener) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(listener);
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(listener => listener(data));
    }
  }
}

class Bank {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.balance = 0;
    this.eventBus.subscribe('bank:deposit', this.deposit.bind(this));
    this.eventBus.subscribe('bank:withdraw', this.withdraw.bind(this));
  }

  deposit(amount) {
    this.balance += amount;
    console.log(`Bank: Deposited ${amount}, new balance is ${this.balance}`);
    this.eventBus.emit('bank:balanceUpdated', this.balance);
  }

  withdraw(amount) {
    if (this.balance >= amount) {
      this.balance -= amount;
      console.log(`Bank: Withdrew ${amount}, new balance is ${this.balance}`);
      this.eventBus.emit('bank:balanceUpdated', this.balance);
    } else {
      console.log('Bank: Insufficient funds');
    }
  }
}

class Market {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.prices = { 'gold': 10, 'silver': 5, 'iron': 1 };
    this.eventBus.subscribe('market:buy', this.buy.bind(this));
    this.eventBus.subscribe('market:sell', this.sell.bind(this));
  }

  buy(item, quantity) {
    const price = this.prices[item] * quantity;
    this.eventBus.emit('bank:withdraw', price);
  }

  sell(item, quantity) {
    const price = this.prices[item] * quantity;
    this.eventBus.emit('bank:deposit', price);
  }
}

class Inventory {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.items = { 'gold': 0, 'silver': 0, 'iron': 0 };
    this.eventBus.subscribe('inventory:add', this.addItem.bind(this));
    this.eventBus.subscribe('inventory:remove', this.removeItem.bind(this));
    this.eventBus.subscribe('bank:balanceUpdated', this.checkBalance.bind(this));
  }

  addItem(item, quantity) {
    this.items[item] = (this.items[item] || 0) + quantity;
    console.log(`Inventory: Added ${quantity} ${item}, total is ${this.items[item]}`);
  }

  removeItem(item, quantity) {
    if (this.items[item] >= quantity) {
      this.items[item] -= quantity;
      console.log(`Inventory: Removed ${quantity} ${item}, total is ${this.items[item]}`);
    } else {
      console.log('Inventory: Insufficient quantity');
    }
  }

  checkBalance(balance) {
    console.log(`Inventory: Current balance is ${balance}`);
  }
}

// Demo
const eventBus = new EventBus();
const bank = new Bank(eventBus);
const market = new Market(eventBus);
const inventory = new Inventory(eventBus);

console.log('Demo: Deposit 100 gold into the bank');
eventBus.emit('bank:deposit', 100);

console.log('Demo: Buy 5 gold from the market');
eventBus.emit('market:buy', 'gold', 5);

console.log('Demo: Add 5 gold to the inventory');
eventBus.emit('inventory:add', 'gold', 5);

console.log('Demo: Remove 3 gold from the inventory');
eventBus.emit('inventory:remove', 'gold', 3);

console.log('Demo: Sell 2 gold to the market');
eventBus.emit('market:sell', 'gold', 2);
