// Tower Defense Skirmish with High-Score Saved to localStorage

const canvas = document.createElement('canvas');
document.body.appendChild(canvas);

function resizeCanvas() {
  const dpr = window.devicePixelRatio || 1;
  const rect = canvas.getBoundingClientRect();
  canvas.width = Math.round(rect.width * dpr);
  canvas.height = Math.round(rect.height * dpr);
  canvas.style.width = `${rect.width}px`;
  canvas.style.height = `${rect.height}px`;
  ctx.scale(dpr, dpr);
}

window.addEventListener('resize', resizeCanvas);
resizeCanvas();

const ctx = canvas.getContext('2d');

const enemies = [];
const towers = [];
const projectiles = [];
let score = 0;
let highScore = localStorage.getItem('highScore') || 0;

function spawnEnemy() {
  const x = canvas.width;
  const y = Math.random() * canvas.height;
  enemies.push({ x, y, speed: 2 + Math.random() });
}

function drawEnemy(enemy) {
  ctx.fillStyle = 'red';
  ctx.beginPath();
  ctx.arc(enemy.x, enemy.y, 10, 0, Math.PI * 2);
  ctx.fill();
}

function updateEnemies() {
  enemies.forEach(enemy => {
    enemy.x -= enemy.speed;
    if (enemy.x < 0) {
      enemies.splice(enemies.indexOf(enemy), 1);
      score -= 10;
    }
  });
}

function spawnTower() {
  const x = canvas.width / 2;
  const y = canvas.height / 2;
  towers.push({ x, y, range: 100, power: 1 });
}

function drawTower(tower) {
  ctx.fillStyle = 'green';
  ctx.beginPath();
  ctx.rect(tower.x - 5, tower.y - 5, 10, 10);
  ctx.fill();
}

function updateTowers() {
  towers.forEach(tower => {
    const enemy = enemies.find(e => Math.sqrt((e.x - tower.x) ** 2 + (e.y - tower.y) ** 2) <= tower.range);
    if (enemy) {
      projectiles.push({ x: tower.x, y: tower.y, target: enemy, speed: 5 });
    }
  });
}

function drawProjectile(projectile) {
  ctx.fillStyle = 'blue';
  ctx.beginPath();
  ctx.arc(projectile.x, projectile.y, 5, 0, Math.PI * 2);
  ctx.fill();
}

function updateProjectiles() {
  projectiles.forEach(projectile => {
    const dx = projectile.target.x - projectile.x;
    const dy = projectile.target.y - projectile.y;
    const dist = Math.sqrt(dx ** 2 + dy ** 2);
    projectile.x += (dx / dist) * projectile.speed;
    projectile.y += (dy / dist) * projectile.speed;
    if (Math.sqrt((projectile.x - projectile.target.x) ** 2 + (projectile.y - projectile.target.y) ** 2) < 5) {
      enemies.splice(enemies.indexOf(projectile.target), 1);
      score += 10;
      projectiles.splice(projectiles.indexOf(projectile), 1);
    }
  });
}

function drawScore() {
  ctx.fillStyle = 'black';
  ctx.font = '20px Arial';
  ctx.fillText(`Score: ${score}`, 10, 30);
  ctx.fillText(`High Score: ${highScore}`, 10, 50);
}

function update() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  spawnEnemy();
  updateEnemies();
  enemies.forEach(drawEnemy);

  spawnTower();
  updateTowers();
  towers.forEach(drawTower);

  updateProjectiles();
  projectiles.forEach(drawProjectile);

  drawScore();

  if (score > highScore) {
    highScore = score;
    localStorage.setItem('highScore', highScore);
  }

  requestAnimationFrame(update);
}

update();
