class Bank {
  constructor() {
    this.balance = 0;
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
      return true;
    }
    return false;
  }

  withdraw(amount) {
    if (amount > 0 && this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }

  getBalance() {
    return this.balance;
  }
}

class Market {
  constructor(prices) {
    this.prices = prices;
  }

  buy(item, quantity) {
    if (this.prices[item] !== undefined && quantity > 0) {
      return this.prices[item] * quantity;
    }
    return 0;
  }

  sell(item, quantity) {
    if (this.prices[item] !== undefined && quantity > 0) {
      return this.prices[item] * quantity;
    }
    return 0;
  }

  getPrice(item) {
    return this.prices[item] || 0;
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity) {
    if (quantity > 0) {
      if (this.items[item] === undefined) {
        this.items[item] = 0;
      }
      this.items[item] += quantity;
      return true;
    }
    return false;
  }

  removeItem(item, quantity) {
    if (this.items[item] !== undefined && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      return true;
    }
    return false;
  }

  getItemCount(item) {
    return this.items[item] || 0;
  }
}

class GameCoordinator {
  constructor(bank, market, inventory) {
    this.bank = bank;
    this.market = market;
    this.inventory = inventory;
  }

  buyItem(item, quantity) {
    const cost = this.market.buy(item, quantity);
    if (this.bank.withdraw(cost)) {
      this.inventory.addItem(item, quantity);
      return true;
    }
    return false;
  }

  sellItem(item, quantity) {
    const earnings = this.market.sell(item, quantity);
    if (this.inventory.removeItem(item, quantity)) {
      this.bank.deposit(earnings);
      return true;
    }
    return false;
  }

  getBalance() {
    return this.bank.getBalance();
  }

  getItemCount(item) {
    return this.inventory.getItemCount(item);
  }

  getItemPrice(item) {
    return this.market.getPrice(item);
  }
}

