class EventBus {
  constructor() {
    this.listeners = {};
  }

  subscribe(event, callback) {
    if (!this.listeners[event]) {
      this.listeners[event] = [];
    }
    this.listeners[event].push(callback);
  }

  emit(event, data) {
    if (this.listeners[event]) {
      this.listeners[event].forEach(callback => callback(data));
    }
  }
}

class TradeSystem {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('resourceSold', this.onResourceSold.bind(this));
    this.eventBus.subscribe('resourceBought', this.onResourceBought.bind(this));
  }

  sellResource(resource, amount, price) {
    console.log(`Trade: Sold ${amount} of ${resource} for ${price} gold.`);
    this.eventBus.emit('resourceSold', { resource, amount, price });
  }

  buyResource(resource, amount, price) {
    console.log(`Trade: Bought ${amount} of ${resource} for ${price} gold.`);
    this.eventBus.emit('resourceBought', { resource, amount, price });
  }

  onResourceSold(data) {
    console.log(`Trade: ${data.amount} of ${data.resource} sold at ${data.price} gold each.`);
  }

  onResourceBought(data) {
    console.log(`Trade: ${data.amount} of ${data.resource} bought at ${data.price} gold each.`);
  }
}

class ReputationSystem {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.reputation = 0;
    this.eventBus.subscribe('resourceSold', this.onResourceSold.bind(this));
    this.eventBus.subscribe('resourceBought', this.onResourceBought.bind(this));
  }

  onResourceSold(data) {
    this.reputation += data.amount * 0.1; // Increase reputation for selling
    console.log(`Reputation: Reputation increased by ${data.amount * 0.1} for selling ${data.amount} of ${data.resource}. Current reputation: ${this.reputation}`);
  }

  onResourceBought(data) {
    this.reputation -= data.amount * 0.1; // Decrease reputation for buying
    console.log(`Reputation: Reputation decreased by ${data.amount * 0.1} for buying ${data.amount} of ${data.resource}. Current reputation: ${this.reputation}`);
  }
}

