class Bank {
  constructor(initialBalance = 0) {
    this.balance = initialBalance;
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
      console.log(`Deposited ${amount}. New balance: ${this.balance}`);
    } else {
      console.log('Deposit amount must be positive.');
    }
  }

  withdraw(amount) {
    if (amount > 0 && this.balance >= amount) {
      this.balance -= amount;
      console.log(`Withdrew ${amount}. New balance: ${this.balance}`);
    } else if (amount > 0) {
      console.log('Insufficient funds.');
    } else {
      console.log('Withdrawal amount must be positive.');
    }
  }

  getBalance() {
    return this.balance;
  }
}

class Market {
  constructor(prices = {}) {
    this.prices = prices;
  }

  buy(item, amount, bank) {
    const price = this.prices[item];
    if (price !== undefined && amount > 0) {
      const totalCost = price * amount;
      if (bank.getBalance() >= totalCost) {
        bank.withdraw(totalCost);
        console.log(`Bought ${amount} ${item}(s) for ${totalCost}.`);
        return amount;
      } else {
        console.log('Insufficient balance to buy item.');
        return 0;
      }
    } else {
      console.log('Invalid item or amount.');
      return 0;
    }
  }

  sell(item, amount, bank) {
    const price = this.prices[item];
    if (price !== undefined && amount > 0) {
      const totalRevenue = price * amount;
      bank.deposit(totalRevenue);
      console.log(`Sold ${amount} ${item}(s) for ${totalRevenue}.`);
      return totalRevenue;
    } else {
      console.log('Invalid item or amount.');
      return 0;
    }
  }

  getPrice(item) {
    return this.prices[item] !== undefined ? this.prices[item] : 'Item not found.';
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, amount) {
    if (amount > 0) {
      this.items[item] = (this.items[item] || 0) + amount;
      console.log(`Added ${amount} ${item}(s). Total: ${this.items[item]}`);
    } else {
      console.log('Amount must be positive.');
    }
  }

  removeItem(item, amount) {
    if (this.items[item] !== undefined && amount > 0 && this.items[item] >= amount) {
      this.items[item] -= amount;
      console.log(`Removed ${amount} ${item}(s). Remaining: ${this.items[item]}`);
      return amount;
    } else if (this.items[item] !== undefined && amount > 0) {
      console.log('Insufficient quantity to remove.');
      return 0;
    } else {
      console.log('Invalid item or amount.');
      return 0;
    }
  }

  getInventory() {
    return this.items;
  }
}

// Demo
const bank = new Bank(1000);
const market = new Market({ apple: 2, banana: 1 });
const inventory = new Inventory();

// Player buys apples from the market
const applesBought = market.buy('apple', 5, bank);
inventory.addItem('apple', applesBought);

// Player sells some apples back to the market
const applesSold = inventory.removeItem('apple', 3);
const revenue = market.sell('apple', applesSold, bank);

// Player buys bananas from the market
