    this.balance = 0;
    this.eventBus = eventBus;
    this.eventBus.subscribe('purchaseAttempt', this.handlePurchaseAttempt.bind(this));
    this.eventBus.subscribe('sellAttempt', this.handleSellAttempt.bind(this));
  }

  deposit(amount) {
    this.balance += amount;
    console.log(`Deposited ${amount}. New balance: ${this.balance}`);
  }

  withdraw(amount) {
    if (this.balance >= amount) {
      this.balance -= amount;
      console.log(`Withdrew ${amount}. New balance: ${this.balance}`);
      return true;
    } else {
      console.log(`Insufficient funds. Balance: ${this.balance}`);
      return false;
    }
  }

  handlePurchaseAttempt({ itemPrice, item }) {
    if (this.withdraw(itemPrice)) {
      this.eventBus.emit('purchaseSuccess', { item });
    } else {
      this.eventBus.emit('purchaseFailure', { item });
    }
  }

  handleSellAttempt({ itemPrice, item }) {
    this.deposit(itemPrice);
    console.log(`Sold ${item} for ${itemPrice}. New balance: ${this.balance}`);
  }
}

