// Initialize canvas and context
const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

// Constants
const GRID_SIZE = 50;
const PLAYER_SIZE = GRID_SIZE * 2;
const ENEMY_SIZE = GRID_SIZE * 2;
const PLAYER_SPEED = 5;
const ENEMY_SPEED = 3;
const COOLDOWN = 1000; // milliseconds

// Game state
let playerX = GRID_SIZE * 2;
let playerY = GRID_SIZE * 2;
let enemyX = canvas.width - GRID_SIZE * 4;
let enemyY = canvas.height - GRID_SIZE * 4;
let playerHealth = 100;
let enemyHealth = 100;
let playerTurn = true;
let cooldownTimer = 0;
let score = 0;
let highScore = localStorage.getItem('highScore') || 0;

// Load images
const playerImg = new Image();
playerImg.src = 'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAADIA...';
const enemyImg = new Image();
enemyImg.src = 'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAADIA...';

// Event listeners
document.addEventListener('keydown', (e) => {
    if (!playerTurn) return;
    switch (e.key) {
        case 'ArrowUp':
            playerY -= PLAYER_SPEED;
            break;
        case 'ArrowDown':
            playerY += PLAYER_SPEED;
            break;
        case 'ArrowLeft':
            playerX -= PLAYER_SPEED;
            break;
        case 'ArrowRight':
            playerX += PLAYER_SPEED;
            break;
        case 'Space':
            if (cooldownTimer <= 0) {
                attack(enemyX, enemyY, ENEMY_SIZE);
                cooldownTimer = COOLDOWN;
            }
            break;
    }
});

// Game loop
function gameLoop(timestamp) {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw player
    ctx.drawImage(playerImg, playerX, playerY, PLAYER_SIZE, PLAYER_SIZE);

    // Draw enemy
    ctx.drawImage(enemyImg, enemyX, enemyY, ENEMY_SIZE, ENEMY_SIZE);

    // Draw health bars
    ctx.fillStyle = 'red';
    ctx.fillRect(10, 10, 200, 20);
    ctx.fillRect(canvas.width - 210, 10, 200, 20);
    ctx.fillStyle = 'green';
    ctx.fillRect(10, 10, (playerHealth / 100) * 200, 20);
    ctx.fillRect(canvas.width - 210, 10, (enemyHealth / 100) * 200, 20);

    // Draw score
    ctx.fillStyle = 'black';
    ctx.font = '20px Arial';
    ctx.fillText(`Score: ${score}`, 10, 40);
    ctx.fillText(`High Score: ${highScore}`, canvas.width - 150, 40);

    // Enemy turn
    if (!playerTurn) {
        enemyMove();
        if (Math.random() < 0.5 && cooldownTimer <= 0) {
            attack(playerX, playerY, PLAYER_SIZE);
            cooldownTimer = COOLDOWN;
        }
    }

    // Update cooldown
    if (cooldownTimer > 0) cooldownTimer -= 16;

    // Check win/lose
    if (playerHealth <= 0) {
        alert('You Lose!');
        if (score > highScore) {
            highScore = score;
            localStorage.setItem('highScore', highScore);
        }
        resetGame();
    } else if (enemyHealth <= 0) {
        alert('You Win!');
        score++;
        resetGame();
    }

    requestAnimationFrame(gameLoop);
}

// Enemy movement
function enemyMove() {
    const direction = Math.random() < 0.5 ? -1 : 1;
    if (Math.random() < 0.5) {
        enemyX += ENEMY_SPEED * direction;
    } else {
        enemyY += ENEMY_SPEED * direction;
    }
}

// Attack function
function attack(targetX, targetY, targetSize) {
    const distance = Math.sqrt((playerX - targetX) ** 2 + (playerY - targetY) ** 2);
    if (distance < PLAYER_SIZE + targetSize) {
        if (playerTurn) {
            enemyHealth -= 10;
        } else {
            playerHealth -= 10;
        }
    }
}

// Reset game
function resetGame() {
    playerX = GRID_SIZE * 2;
    playerY = GRID_SIZE * 2;
    enemyX = canvas.width - GRID_SIZE * 4;
    enemyY = canvas.height - GRID_SIZE * 4;
    playerHealth = 100;
    enemyHealth = 100;
    playerTurn = true;
}

// Start game loop
requestAnimationFrame(gameLoop);
