const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

canvas.width = 800;
canvas.height = 600;

const mazeWidth = 40;
const mazeHeight = 30;
const cellSize = 20;
const wallThickness = 4;

const player = {
    x: mazeWidth / 2,
    y: mazeHeight / 2,
    speed: 3,
    direction: { x: 0, y: 0 }
};

const maze = Array.from({ length: mazeHeight }, () =>
    Array(mazeWidth).fill(0)
);

function generateMaze() {
    const stack = [];
    const visited = Array.from({ length: mazeHeight }, () =>
        Array(mazeWidth).fill(false)
    );

    const directions = [
        { x: 0, y: -2 }, // Up
        { x: 2, y: 0 },  // Right
        { x: 0, y: 2 },  // Down
        { x: -2, y: 0 }  // Left
    ];

    function carve(x, y) {
        visited[y][x] = true;
        stack.push({ x, y });

        while (stack.length > 0) {
            const { x, y } = stack[stack.length - 1];
            let canMove = false;

            for (const { x: dx, y: dy } of directions) {
                const nx = x + dx;
                const ny = y + dy;

                if (nx >= 0 && nx < mazeWidth && ny >= 0 && ny < mazeHeight && !visited[ny][nx]) {
                    maze[ny + dy / 2][nx + dx / 2] = 1;
                    visited[ny][nx] = true;
                    stack.push({ x: nx, y: ny });
                    canMove = true;
                    break;
                }
            }

            if (!canMove) {
                stack.pop();
            }
        }
    }

    carve(1, 1);
}

function drawMaze() {
    ctx.fillStyle = '#000';
    for (let y = 0; y < mazeHeight; y++) {
        for (let x = 0; x < mazeWidth; x++) {
            if (maze[y][x] === 1) {
                ctx.fillRect(x * cellSize, y * cellSize, cellSize, cellSize);
            }
        }
    }
}

function drawPlayer() {
    ctx.fillStyle = '#0f0';
    ctx.fillRect(player.x * cellSize, player.y * cellSize, cellSize, cellSize);
}

const particles = [];

function createParticle(x, y, color) {
    particles.push({
        x: x * cellSize + cellSize / 2,
        y: y * cellSize + cellSize / 2,
        size: Math.random() * 2 + 1,
        color: color,
        lifetime: Math.random() * 50 + 50
    });
}

function drawParticles() {
    ctx.globalAlpha = 0.8;
    particles.forEach(particle => {
        ctx.fillStyle = particle.color;
        ctx.beginPath();
        ctx.arc(particle.x, particle.y, particle.size, 0, Math.PI * 2);
        ctx.fill();
    });
    ctx.globalAlpha = 1;
}

function updateParticles() {
    particles.forEach((particle, index) => {
        particle.lifetime--;
        if (particle.lifetime <= 0) {
            particles.splice(index, 1);
        }
    });
}

function checkCollision(x, y) {
    return maze[Math.floor(y)][Math.floor(x)] === 1;
}

function updatePlayer() {
    const nx = player.x + player.direction.x * player.speed;
    const ny = player.y + player.direction.y * player.speed;

    if (!checkCollision(nx, ny)) {
        player.x = nx;
        player.y = ny;
        createParticle(player.x, player.y, '#0f0');
    }
}

document.addEventListener('keydown', (e) => {
    switch (e.key) {
        case 'ArrowUp':
            player.direction = { x: 0, y: -1 };
            break;
        case 'ArrowDown':
            player.direction = { x: 0, y: 1 };
            break;
        case 'ArrowLeft':
            player.direction = { x: -1, y: 0 };
            break;
        case 'ArrowRight':
            player.direction = { x: 1, y: 0 };
            break;
    }
});

document.addEventListener('keyup', () => {
    player.direction = { x: 0, y: 0 };
});

generateMaze();

const fixedTimestep = 1000 / 60;
let lastTime = 0;

function gameLoop(timestamp) {
    const deltaTime = timestamp - lastTime;
    lastTime = timestamp;

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    drawMaze();
    updatePlayer();
    drawPlayer();
    updateParticles();
    drawParticles();

    requestAnimationFrame(gameLoop);
}

requestAnimationFrame(gameLoop);
