const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const gravity = 0.5;
const flapStrength = -10;
const pipeWidth = 75;
const pipeGap = 150;
const birdWidth = 34;
const birdHeight = 24;
const birdX = 100;
let birdY = canvas.height / 2;
let birdVelocity = 0;
let score = 0;
let pipes = [];
let state = 'menu';
let lastTime = 0;

function Bird() {
    this.x = birdX;
    this.y = birdY;
    this.velocity = birdVelocity;
    this.width = birdWidth;
    this.height = birdHeight;

    this.update = function(delta) {
        if (state === 'playing') {
            this.velocity += gravity;
            this.y += this.velocity * delta;
            this.velocity *= 0.95; // Air resistance

            if (this.y > canvas.height - this.height) {
                this.y = canvas.height - this.height;
                this.velocity = 0;
                changeState('gameover');
            } else if (this.y < 0) {
                this.y = 0;
                this.velocity = 0;
            }
        }
    };

    this.draw = function() {
        ctx.fillStyle = 'yellow';
        ctx.fillRect(this.x, this.y, this.width, this.height);
    };

    this.flap = function() {
        if (state === 'playing') {
            this.velocity = flapStrength;
        }
    };
}

function Pipe() {
    this.width = pipeWidth;
    this.height = Math.random() * (canvas.height - pipeGap) + pipeGap / 2;
    this.x = canvas.width;
    this.gap = pipeGap;

    this.update = function(delta) {
        if (state === 'playing') {
            this.x -= 200 * delta;
        }
    };

    this.draw = function() {
        ctx.fillStyle = 'green';
        ctx.fillRect(this.x, 0, this.width, this.height);
        ctx.fillRect(this.x, this.height + this.gap, this.width, canvas.height);
    };

    this.collidesWith = function(bird) {
        return this.x < bird.x + bird.width &&
               this.x + this.width > bird.x &&
               (bird.y < this.height || bird.y + bird.height > this.height + this.gap);
    };
}

function changeState(newState) {
    state = newState;
    if (newState === 'playing') {
        birdY = canvas.height / 2;
        birdVelocity = 0;
        score = 0;
        pipes = [];
    }
}

function update(delta) {
    bird.update(delta);

    if (state === 'playing') {
        if (pipes.length === 0 || pipes[pipes.length - 1].x < canvas.width - 300) {
            pipes.push(new Pipe());
        }

        pipes.forEach(pipe => {
            pipe.update(delta);
            if (pipe.collidesWith(bird)) {
                changeState('gameover');
            }
            if (pipe.x + pipe.width < bird.x && !pipe.scored) {
                score++;
                pipe.scored = true;
            }
        });

        pipes = pipes.filter(pipe => pipe.x + pipe.width > 0);
    }
}

function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    bird.draw();
    pipes.forEach(pipe => pipe.draw());

    ctx.fillStyle = 'black';
    ctx.font = '30px Arial';
    ctx.fillText(`Score: ${score}`, 10, 30);

    if (state === 'menu') {
        ctx.fillText('Click to Start', canvas.width / 2 - 100, canvas.height / 2);
    } else if (state === 'paused') {
        ctx.fillText('Paused', canvas.width / 2 - 50, canvas.height / 2);
    } else if (state === 'gameover') {
        ctx.fillText('Game Over', canvas.width / 2 - 80, canvas.height / 2);
        ctx.fillText('Click to Restart', canvas.width / 2 - 120, canvas.height / 2 + 40);
    }
}

function mainLoop(timestamp) {
    const delta = (timestamp - lastTime) / 1000;
    lastTime = timestamp;

    update(delta);
    draw();

    requestAnimationFrame(mainLoop);
}

canvas.addEventListener('click', () => {
    if (state === 'menu' || state === 'gameover') {
        changeState('playing');
    } else if (state === 'playing') {
        changeState('paused');
    } else if (state === 'paused') {
        changeState('playing');
    }
});

canvas.addEventListener('keydown', (e) => {
    if (e.code === 'Space') {
        bird.flap();
    }
});

const bird = new Bird();
mainLoop(performance.now());
