// Define the game states
const STATES = {
  MENU: 'menu',
  PLAYING: 'playing',
  PAUSED: 'paused',
  GAMEOVER: 'gameover'
};

// Game configuration
const config = {
  canvasWidth: 800,
  canvasHeight: 600,
  cardWidth: 100,
  cardHeight: 150,
  cardPadding: 10,
  cardCount: 16,
  flipDuration: 500, // milliseconds
  fps: 60,
  tps: 30 // ticks per second for the game logic
};

// Initialize the canvas
const canvas = document.createElement('canvas');
canvas.width = config.canvasWidth;
canvas.height = config.canvasHeight;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

// Game variables
let state = STATES.MENU;
let cards = [];
let flippedCards = [];
let matchedCards = [];
let startTime = null;
let pauseTime = null;
let elapsedGameTime = 0;
let lastTickTime = 0;
let ticks = 0;

// Load images
const cardBackImage = new Image();
cardBackImage.src = 'https://via.placeholder.com/100x150?text=Back';

// Card class
class Card {
  constructor(x, y, image) {
    this.x = x;
    this.y = y;
    this.image = image;
    this.flipped = false;
    this.matched = false;
  }

  draw() {
    if (this.flipped || this.matched) {
      ctx.drawImage(this.image, this.x, this.y, config.cardWidth, config.cardHeight);
    } else {
      ctx.drawImage(cardBackImage, this.x, this.y, config.cardWidth, config.cardHeight);
    }
  }
}

// Initialize game
function initGame() {
  state = STATES.PLAYING;
  startTime = Date.now();
  pauseTime = null;
  elapsedGameTime = 0;
  ticks = 0;
  cards = [];
  flippedCards = [];
  matchedCards = [];

  const images = [];
  for (let i = 0; i < config.cardCount / 2; i++) {
    const img = new Image();
    img.src = `https://via.placeholder.com/100x150?text=${i + 1}`;
    images.push(img, img);
  }

  images.sort(() => Math.random() - 0.5);

  let x = config.cardPadding;
  let y = config.cardPadding;
  for (let i = 0; i < images.length; i++) {
    cards.push(new Card(x, y, images[i]));
    x += config.cardWidth + config.cardPadding;
    if (x + config.cardWidth > config.canvasWidth) {
      x = config.cardPadding;
      y += config.cardHeight + config.cardPadding;
    }
  }
}

// Update game logic
function update(deltaTime) {
  if (state === STATES.PLAYING) {
    ticks++;
    if (ticks % (config.tps / config.fps) === 0) {
      // Update game logic at TPS
      if (flippedCards.length === 2) {
        if (flippedCards[0].image === flippedCards[1].image) {
          matchedCards.push(...flippedCards);
        }
        setTimeout(() => {
          flippedCards[0].flipped = false;
          flippedCards[1].flipped = false;
          flippedCards.length = 0;
        }, config.flipDuration);
      }
    }
  }
}

// Render the game
function render() {
  ctx.clearRect(0, 0, config.canvasWidth, config.canvasHeight);

  if (state === STATES.MENU) {
    ctx.font = '36px Arial';
    ctx.textAlign = 'center';
    ctx.fillText('Memory Game', config.canvasWidth / 2, config.canvasHeight / 2);
    ctx.fillText('Click to Start', config.canvasWidth / 2, config.canvasHeight / 2 + 50);
  } else if (state === STATES.PLAYING || state === STATES.PAUSED) {
    cards.forEach(card => card.draw());
  } else if (state === STATES.GAMEOVER) {
    ctx.font = '36px Arial';
    ctx.textAlign = 'center';
    ctx.fillText('Game Over', config.canvasWidth / 2, config.canvasHeight / 2);
    ctx.fillText('Click to Restart', config.canvasWidth / 2, config.canvasHeight / 2 + 50);
  }
}

// Main game loop
function gameLoop(timestamp) {
  const now = timestamp / 1000;
  const deltaTime = now - lastTickTime;
  lastTickTime = now;

  if (startTime !== null) {
    elapsedGameTime = now - startTime - (pauseTime !== null ? pauseTime : 0);
  }

  update(deltaTime);
  render();

  requestAnimationFrame(gameLoop);
}

// Event listeners
canvas.addEventListener('click', (event) => {
  if (state === STATES.MENU) {
    initGame();
  } else if (state === STATES.PLAYING) {
    const rect = canvas.getBoundingClientRect();
    const x = event.clientX - rect.left;
    const y = event.clientY - rect.top;

    cards.forEach(card => {
      if (card.x < x && x < card.x + config.cardWidth && card.y < y && y < card.y + config.cardHeight) {
        if (!card.flipped && !card.matched && flippedCards.length < 2) {
          card.flipped = true;
          flippedCards.push(card);
        }
      }
    });

    if (matchedCards.length === config.cardCount) {
      state = STATES.GAMEOVER;
    }
  } else if (state === STATES.PAUSED) {
    state = STATES.PLAYING;
    pauseTime = null;
    startTime += Date.now() - lastTickTime;
  } else if (state === STATES.GAMEOVER) {
    initGame();
  }
});

canvas.addEventListener('dblclick', (event) => {
  if (state === STATES.PLAYING) {
    state = STATES.PAUSED;
    pauseTime = Date.now() - lastTickTime;
  }
});

// Start the game loop
requestAnimationFrame(gameLoop);
