            });
        }

        this.helpText.setText(this.getHelpMessage());
    }

    getHelpMessage ()
    {
        return `Arrow keys to move.\nPress "C" to toggle debug visuals: ${this.showDebug ? 'on' : 'off'}`;
    }
}

